# ===================================================================== reference

NEVER = 10 ** 15
SHIPPED_CONV = {'hr': 'site', 'start': 'decided', 'window': 'half'}
STAMP = re.compile(r"(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d):(\d\d)(?:(Z)|([+-])(\d\d):(\d\d))")
DAYRX = re.compile(r"(\d{4})-(\d\d)-(\d\d)")
EMPRX = re.compile(r"(?:[Ee]-?)?(\d{1,6})")
CTRRX = re.compile(r"(?:[Cc][Tt][Rr]-?|[Cc]-?)(\d{1,4})")
MFARX = re.compile(r"(.+?) (\S+) (\S+) handle=(\S+) recorded=(\S+)")
KINDS = ("invisible", "rejected", "unresolved", "collapsed", "accepted")


class Bad(Exception):
    pass


@functools.lru_cache(maxsize=None)
def _epoch(y, mo, d, h=0, mi=0, s=0):
    if not (1 <= mo <= 12) or not (1 <= d <= calendar.monthrange(y, mo)[1]) or h > 23 or mi > 59 or s > 59:
        raise Bad()
    return calendar.timegm((y, mo, d, h, mi, s))


_STAMPS = {}


def stamp(v):
    if type(v) is str and v in _STAMPS:
        return _STAMPS[v]
    out = _stamp(v)
    _STAMPS[v] = out
    return out


def _stamp(v):
    if type(v) is not str:
        raise Bad()
    m = STAMP.fullmatch(v)
    if m is None:
        raise Bad()
    t = _epoch(*(int(m.group(i)) for i in range(1, 7)))
    if m.group(7):
        return t
    oh, om = int(m.group(9)), int(m.group(10))
    if oh > 23 or om > 59:
        raise Bad()
    shift = oh * 3600 + om * 60
    return t - shift if m.group(8) == "+" else t + shift


def day(v):
    if type(v) is not str:
        raise Bad()
    m = DAYRX.fullmatch(v)
    if m is None:
        raise Bad()
    y, mo, d = (int(x) for x in m.groups())
    _epoch(y, mo, d)
    return (y, mo, d)


def epoch_int(v):
    if type(v) is int:
        return v
    if type(v) is str and v.isdigit():
        return int(v)
    raise Bad()


def utc(t):
    return "open" if t >= NEVER else datetime.fromtimestamp(t, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def shift_day(dd, n):
    g = datetime.fromtimestamp(_epoch(*dd) + n * 86400, timezone.utc)
    return (g.year, g.month, g.day)


class Clock:
    def __init__(self, zones):
        self.z = {}
        for name, spec in zones.items():
            std = spec["std_offset_min"] * 60
            dst = spec.get("dst_offset_min", spec["std_offset_min"]) * 60
            marks = sorted((stamp(a), k) for a, k in spec.get("transitions", []))
            self.z[name] = (std, dst, [m[0] for m in marks], [m[1] for m in marks])

    def offset(self, name, t):
        std, dst, at, kind = self.z[name]
        if not at:
            return std
        i = bisect.bisect_right(at, t)
        k = kind[i - 1] if i else ("dst" if kind[0] == "std" else "std")
        return dst if k == "dst" else std

    def wall(self, name, dd, h=0, mi=0):
        local = _epoch(dd[0], dd[1], dd[2], h, mi)
        std, dst, _, _ = self.z[name]
        good = [local - o for o in {std, dst} if self.offset(name, local - o) == o]
        return min(good) if good else local - std

    def date_of(self, name, t):
        g = datetime.fromtimestamp(t + self.offset(name, t), timezone.utc)
        return (g.year, g.month, g.day)


def emp_id(ref):
    if type(ref) is not str:
        return None
    m = EMPRX.fullmatch(ref.strip())
    return "emp:" + m.group(1).rjust(6, "0") if m else None


def ctr_id(ref):
    if type(ref) is not str:
        return None
    m = CTRRX.fullmatch(ref.strip())
    return "ctr:" + m.group(1).rjust(4, "0") if m else None


def lowered(h):
    return h.strip().lower() if type(h) is str else ""


def read_rows(path: Path, kind: str):
    text = path.read_text(encoding="utf-8")
    if kind == "jsonl":
        return [json.loads(x) for x in text.splitlines() if x.strip()]
    if kind == "log":
        out = []
        for x in text.splitlines():
            m = MFARX.fullmatch(x.strip()) if x.strip() and not x.startswith("#") else None
            if m:
                out.append(dict(zip(("at", "event_id", "action", "handle", "recorded_at"), m.groups())))
        return out
    return list(csv.DictReader(io.StringIO(text), delimiter="\t" if kind == "tsv" else ","))


class Book:
    def __init__(self):
        self.tally = defaultdict(lambda: dict.fromkeys(KINDS, 0))
        self.rej = []
        self.unr = []

    def put(self, src, kind, rid=None, why=None):
        self.tally[src][kind] += 1
        if kind == "rejected":
            self.rej.append((src, rid, why))
        elif kind == "unresolved":
            self.unr.append((src, rid, why))


def load(root: Path):
    root = Path(root)
    names = json.loads((root / "corpus_manifest.json").read_text())["files"]
    for n in names:
        if not (root / n).is_file():
            raise FileNotFoundError(n)
    J = lambda n: json.loads((root / n).read_text(encoding="utf-8"))
    D = {"root": root, "names": sorted(names)}
    D["schema"] = J("config_schema.json")
    D["defaults"] = J("defaults.json")["values"]
    D["profiles"] = tomllib.loads((root / "profiles.toml").read_text(encoding="utf-8"))
    cp = configparser.ConfigParser(interpolation=None)
    cp.optionxform = str
    cp.read_string((root / "site_policy.ini").read_text(encoding="utf-8"))
    D["site"] = {s: dict(cp[s]) for s in cp.sections()}
    D["tz"] = J("tz_rules.json")["zones"]
    D["sites"] = J("hr_sites.json")["sites"]
    D["roles"] = J("role_catalog.json")["roles"]
    D["perms"] = tomllib.loads((root / "permission_catalog.toml").read_text(encoding="utf-8"))["permissions"]
    D["sod"] = J("sod_policy.json")["pairs"]
    D["groups"] = {g["id"] for g in J("dir_groups.json")["groups"]}
    D["rot"] = {x["id"]: x for x in J("oncall_rotations.json")["rotations"]}
    D["freeze"] = J("freeze_windows.json")["windows"]

    def many(prefix, suffix, kind):
        out = []
        for n in names:
            if n.startswith(prefix) and n.endswith(suffix):
                for row in read_rows(root / n, kind):
                    out.append((n, row))
        return sorted(out, key=lambda x: x[0]) if False else out

    def one(n, kind):
        return [(n, row) for row in read_rows(root / n, kind)]

    D["journal"] = one("policy_change_journal.jsonl", "jsonl")
    D["emp"] = one("hr_employees.csv", "csv")
    D["hrev"] = many("hr_events_", ".csv", "csv")
    D["hrcorr"] = one("hr_corrections.csv", "csv")
    D["contracts"] = one("contractor_contracts.csv", "csv")
    D["idp"] = many("idp_accounts_", ".jsonl", "jsonl")
    D["mfa"] = one("idp_mfa_events.log", "log")
    D["alias"] = one("directory_aliases.tsv", "tsv")
    D["mem"] = many("dir_members_site_", ".csv", "csv")
    D["rem"] = one("dir_membership_removals.csv", "csv")
    D["bind"] = {e: one(f"role_bindings_{e}.csv", "csv") for e in ("dev", "prod")}
    D["req"] = many("grant_requests_", ".jsonl", "jsonl")
    D["appr"] = one("grant_approvals.csv", "csv")
    D["corr"] = one("grant_corrections.jsonl", "jsonl")
    D["ssr"] = one("revocations_selfservice.csv", "csv")
    D["sec"] = one("revocations_secops.jsonl", "jsonl")
    D["asg"] = one("oncall_assignments.csv", "csv")
    D["swp"] = one("oncall_swaps.csv", "csv")
    D["att"] = one("access_attestations.csv", "csv")
    return D


# --------------------------------------------------------------------------- config
def settle_config(D):
    sch = D["schema"]
    flat = {}
    for k, spec in sch["keys"].items():
        if spec["scope"] == "global":
            flat[k] = spec
        else:
            for p in sch["profiles"]:
                flat[p + "." + k] = spec

    def check(spec, v):
        t = spec["type"]
        if t == "int":
            return type(v) is int and spec["min"] <= v <= spec["max"]
        if t == "bool":
            return type(v) is bool
        return v in spec["values"]

    def from_ini(spec, s):
        s = s.strip()
        if spec["type"] == "int":
            return int(s)
        if spec["type"] == "bool":
            return {"true": True, "false": False}[s]
        return s

    stack = defaultdict(list)
    for k, v in D["defaults"].items():
        targets = [k] if sch["keys"][k]["scope"] == "global" else [p + "." + k for p in sch["profiles"]]
        for t in targets:
            stack[t].append(v)
    for p in sch["profiles"]:
        for k, v in D["profiles"].get(p, {}).items():
            stack[p + "." + k].append(v)
    for sec, kv in D["site"].items():
        if sec == "anchor":
            continue
        for k, v in kv.items():
            name = k if sec == "global" else sec + "." + k
            stack[name].append(from_ini(flat[name], v))
    as_of = stamp(D["site"]["anchor"]["as_of"])
    cut = stamp(D["site"]["anchor"]["recorded_cutoff"])
    rej, tally, live = [], dict.fromkeys(("records",) + KINDS, 0), []
    for src, row in D["journal"]:
        tally["records"] += 1
        rid = str(row.get("seq"))
        try:
            rec = stamp(row.get("recorded_at"))
        except Bad:
            rej.append((src, rid, "bad_timestamp"))
            tally["rejected"] += 1
            continue
        if rec > cut:
            tally["invisible"] += 1
            continue
        why = None
        try:
            eff = stamp(row.get("effective_at"))
        except Bad:
            why = "bad_timestamp"
        key = row.get("key")
        if why is None and "value" not in row:
            why = "missing_field"
        elif why is None and key in sch["anchor_keys"]:
            why = "anchor_key"
        elif why is None and key not in flat:
            why = "unknown_key"
        elif why is None and row["value"] is not None and not check(flat[key], row["value"]):
            why = "out_of_bounds"
        if why:
            rej.append((src, rid, why))
            tally["rejected"] += 1
            continue
        tally["accepted"] += 1
        if eff <= as_of:
            live.append((eff, int(row["seq"]), key, row["value"]))
    jr = defaultdict(list)
    for _, _, key, v in sorted(live):
        if v is None:
            jr[key] = []
        else:
            jr[key].append(v)
    out = {"as_of": utc(as_of), "recorded_cutoff": utc(cut)}
    for name, spec in flat.items():
        vals = stack[name] + jr[name]
        if not vals:
            continue
        if spec.get("class") == "ceiling":
            out[name] = min(vals)
        elif jr[name]:
            out[name] = jr[name][-1]
        else:
            out[name] = stack[name][-1]
    return out, rej, tally


# --------------------------------------------------------------------------- evaluation
class World:
    def __init__(self, D, cfg, conv=None):
        self.D, self.cfg = D, cfg
        self.conv = dict(SHIPPED_CONV, **(conv or {}))
        self.E, self.R = stamp(cfg["as_of"]), stamp(cfg["recorded_cutoff"])
        self.clock = Clock(D["tz"])
        self.book = Book()
        self.role_of = {}
        for name, spec in D["roles"].items():
            for alias in [name] + spec.get("legacy_names", []):
                self.role_of[alias.lower()] = name
        self.expand_cache = {}
        self.run()

    def seen(self, src, rid, raw, unit):
        try:
            v = stamp(raw) if unit == "iso" else epoch_int(raw)
        except Bad:
            self.book.put(src, "rejected", rid, "bad_timestamp")
            return False
        limit = self.R * 1000 if unit == "ms" else self.R
        if v > limit:
            self.book.put(src, "invisible")
            return False
        return True

    def expand(self, role, env):
        key = (role, env)
        if key not in self.expand_cache:
            got, todo, done = set(), [role], set()
            while todo:
                r = todo.pop()
                if r in done:
                    continue
                done.add(r)
                got.update(p for p in self.D["roles"][r].get("permissions", [])
                           if self.D["perms"][p]["scope"] in ("both", env))
                todo += self.D["roles"][r].get("includes", [])
            self.expand_cache[key] = frozenset(got)
        return self.expand_cache[key]

    def who(self, handle):
        h = lowered(handle)
        if h in self.owner:
            return self.owner[h]
        if h in self.aka:
            return self.owner.get(self.aka[h])
        return None

    def who_any(self, ref):
        pid = ctr_id(ref) or emp_id(ref)
        if pid is not None:
            return pid if pid in self.people else None
        return self.who(ref)

    def run(self):
        D, B, E, R = self.D, self.book, self.E, self.R
        # employees
        self.emp_tz = {}
        for src, row in D["emp"]:
            self.emp_tz[emp_id(row["employee_no"])] = D["sites"][row["site"]]["tz"]
            B.put(src, "accepted")
        # contracts
        cands = defaultdict(list)
        for src, row in D["contracts"]:
            rid = row["contractor_id"] + "#" + row["amendment_no"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                a, b = day(row["start_date"]), day(row["end_date"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            if b < a:
                B.put(src, "rejected", rid, "window_inverted")
                continue
            sp = emp_id(row["sponsor"])
            if sp not in self.emp_tz:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            cands[ctr_id(row["contractor_id"])].append((int(row["amendment_no"]), src, a, b, sp, D["sites"][row["site"]]["tz"]))
        self.ctr = {}
        for cid, lst in cands.items():
            lst.sort()
            for x in lst[:-1]:
                B.put(x[1], "collapsed")
            B.put(lst[-1][1], "accepted")
            self.ctr[cid] = lst[-1][2:]
        self.people = set(self.emp_tz) | set(self.ctr)
        # accounts
        prio = [x.strip() for x in self.cfg["idp_shard_priority"].split(",")]
        per = defaultdict(list)
        for src, row in D["idp"]:
            rid = f"{row.get('handle')}#{row.get('generation')}"
            if not self.seen(src, rid, row.get("synced_at"), "iso"):
                continue
            shard = src[len("idp_accounts_"):-len(".jsonl")]
            per[lowered(row["handle"])].append((-int(row["generation"]), prio.index(shard) if shard in prio else 99, src, rid, row))
        self.owner, self.enabled, self.mine = {}, set(), defaultdict(set)
        for h, lst in per.items():
            lst.sort(key=lambda x: (x[0], x[1]))
            for x in lst[1:]:
                B.put(x[2], "collapsed")
            _, _, src, rid, row = lst[0]
            pid = ctr_id(row.get("subject_ref")) or emp_id(row.get("subject_ref"))
            if pid not in self.people:
                B.put(src, "unresolved", rid, "orphan_account")
                self.owner[h] = None
                continue
            B.put(src, "accepted")
            self.owner[h] = pid
            self.mine[pid].add(h)
            if row.get("state") == "enabled":
                self.enabled.add(pid)
        # aliases
        self.aka = {}
        for src, row in D["alias"]:
            if not self.seen(src, row["alias"], row["created_at"], "iso"):
                continue
            a, t = lowered(row["alias"]), lowered(row["handle"])
            if a in self.owner:
                B.put(src, "accepted")
            elif self.owner.get(t) is None:
                B.put(src, "unresolved", row["alias"], "unknown_handle")
            else:
                self.aka[a] = t
                B.put(src, "accepted")
        self.hr_layer()
        # mfa
        self.mfa = defaultdict(list)
        for src, row in D["mfa"]:
            rid = row["event_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                at = stamp(row["at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            pid = self.who(row["handle"])
            if pid is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            B.put(src, "accepted")
            self.mfa[pid].append((at, rid, row["action"]))
        self.directory_layer()
        self.binding_layer()
        self.ticket_layer()
        self.secops_layer()
        self.rota_layer()
        self.attest_layer()

    def hr_layer(self):
        D, B = self.D, self.book
        ev = {}
        for src, row in D["hrev"]:
            rid = row["event_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                dd = day(row["effective_date"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            pid = emp_id(row["employee_no"])
            if pid not in self.emp_tz:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            B.put(src, "accepted")
            ev[rid] = (pid, row["event"], dd)
        latest = {}
        for src, row in D["hrcorr"]:
            rid = row["correction_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            nd = None
            if row["action"] == "redate":
                try:
                    nd = day(row["new_effective_date"])
                except Bad:
                    B.put(src, "rejected", rid, "bad_timestamp")
                    continue
            if row["event_id"] not in ev:
                B.put(src, "accepted")
                continue
            entry = (stamp(row["recorded_at"]), rid, src, row["action"], nd)
            old = latest.get(row["event_id"])
            if old is None or entry[:2] > old[:2]:
                if old is not None:
                    B.put(old[2], "collapsed")
                latest[row["event_id"]] = entry
            else:
                B.put(src, "collapsed")
        for eid, (_, _, src, action, nd) in latest.items():
            B.put(src, "accepted")
            if action == "void":
                del ev[eid]
            else:
                ev[eid] = (ev[eid][0], ev[eid][1], nd)
        self.life = defaultdict(list)
        self.hr_ev = ev
        for eid, (pid, kind, dd) in ev.items():
            self.life[pid].append((self.hr_wall(self.emp_tz[pid], dd), eid, kind))
        for v in self.life.values():
            v.sort()

    def hr_wall(self, tz, dd):
        h = self.conv['hr']
        if h == 'site':
            return self.clock.wall(tz, dd)
        if h == 'utc':
            return _epoch(*dd)
        return self.clock.wall(h[5:], dd)

    def employed(self, pid, t):
        st = False
        for at, _, kind in self.life.get(pid, ()):
            if at > t:
                break
            st = kind in ("hire", "rehire", "leave_end")
        return st

    def employed_until(self, pid, t):
        later = [at for at, _, kind in self.life.get(pid, ()) if at > t and kind in ("terminate", "leave_start")]
        return min(later) if later else NEVER

    def standing_of(self, pid, t):
        if pid.startswith("emp:"):
            return (True, self.employed_until(pid, t)) if self.employed(pid, t) else (False, None)
        a, b, sp, tz = self.ctr[pid]
        lo, hi = self.hr_wall(tz, a), self.hr_wall(tz, shift_day(b, 1))
        if lo <= t < hi and self.employed(sp, t):
            return True, min(hi, self.employed_until(sp, t))
        return False, None

    def directory_layer(self):
        D, B, E = self.D, self.book, self.E
        mem = {}
        for src, row in D["mem"]:
            rid = row["mid"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                added = stamp(row["added_at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            m = row["member"].strip()
            nested = m.startswith("group:")
            if row["group_id"] not in D["groups"] or (nested and m[6:] not in D["groups"]):
                B.put(src, "rejected", rid, "unknown_target")
                continue
            if nested:
                node = "G" + m[6:]
            else:
                pid = self.who(m)
                if pid is None:
                    B.put(src, "unresolved", rid, "unknown_handle")
                    continue
                node = "P" + pid
            B.put(src, "accepted")
            mem[rid] = [node, row["group_id"], added, NEVER]
        for src, row in D["rem"]:
            rid = row["removal_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                gone = stamp(row["removed_at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            B.put(src, "accepted")
            if row["mid"] in mem:
                mem[row["mid"]][3] = min(mem[row["mid"]][3], gone)
        self.out_edges = defaultdict(list)
        for node, grp, added, gone in mem.values():
            if added <= E < gone:
                self.out_edges[node].append(("G" + grp, gone))

    def widest(self, pid):
        best = {}
        frontier = [(-cap, node) for node, cap in self.out_edges.get("P" + pid, ())]
        heapq.heapify(frontier)
        while frontier:
            c, node = heapq.heappop(frontier)
            if node in best:
                continue
            best[node] = -c
            for nxt, cap in self.out_edges.get(node, ()):
                if nxt not in best:
                    heapq.heappush(frontier, (max(c, -cap), nxt))
        return {k[1:]: v for k, v in best.items()}

    def binding_layer(self):
        D, B, E = self.D, self.book, self.E
        self.binds = {}
        for env in ("dev", "prod"):
            table = defaultdict(list)
            for src, row in D["bind"][env]:
                rid = row["binding_id"]
                if not self.seen(src, rid, row["recorded_at"], "iso"):
                    continue
                try:
                    lo = stamp(row["bound_from"])
                    hi = stamp(row["bound_until"]) if row["bound_until"] else NEVER
                except Bad:
                    B.put(src, "rejected", rid, "bad_timestamp")
                    continue
                if hi <= lo:
                    B.put(src, "rejected", rid, "window_inverted")
                    continue
                role = self.role_of.get(row["role"].strip().lower())
                if role is None or row["group_id"] not in D["groups"]:
                    B.put(src, "rejected", rid, "unknown_target")
                    continue
                B.put(src, "accepted")
                if lo <= E < hi:
                    table[row["group_id"]].append((role, hi))
            self.binds[env] = table

    def ticket_layer(self):
        D, B, E, R, cfg = self.D, self.book, self.E, self.R, self.cfg
        byid = defaultdict(list)
        for src, row in D["req"]:
            rid = str(row.get("ticket"))
            if self.seen(src, rid, row.get("recorded_at"), "iso"):
                byid[rid].append((src, row))
        self.tk = {}
        for rid, lst in byid.items():
            gen = max(int(r["export_generation"]) for _, r in lst)
            top = sorted([x for x in lst if int(x[1]["export_generation"]) == gen], key=lambda x: x[0])
            for src, r in lst:
                if int(r["export_generation"]) < gen:
                    B.put(src, "collapsed")
            if len({json.dumps(r, sort_keys=True) for _, r in top}) > 1:
                for src, _ in top:
                    B.put(src, "unresolved", rid, "conflicting_duplicate")
                continue
            for src, _ in top[1:]:
                B.put(src, "collapsed")
            src, row = top[0]
            if "effective_from" not in row or "effective_until" not in row:
                B.put(src, "rejected", rid, "missing_field")
                continue
            try:
                frm = None if row["effective_from"] is None else stamp(row["effective_from"])
                til = None if row["effective_until"] is None else stamp(row["effective_until"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            if frm is not None and til is not None and til <= frm:
                B.put(src, "rejected", rid, "window_inverted")
                continue
            env, target = row["env"], row.get("target")
            perms, why = None, "unknown_target"
            if type(target) is str and target.startswith("role:"):
                role = self.role_of.get(target[5:].strip().lower())
                if role:
                    perms, why = self.expand(role, env), None
            elif type(target) is str and target.startswith("perm:"):
                spec = D["perms"].get(target[5:])
                if spec is not None:
                    if spec["scope"] in ("both", env):
                        perms, why = frozenset([target[5:]]), None
                    else:
                        why = "out_of_scope"
            if why:
                B.put(src, "rejected", rid, why)
                continue
            ben, req = self.who(row.get("beneficiary")), self.who(row.get("requester"))
            if ben is None or req is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            self.tk[rid] = dict(src=src, env=env, ben=ben, req=req, perms=perms, frm=frm, til=til,
                                rec=stamp(row["recorded_at"]), votes=[], fix=None, cut=NEVER)
        for src, row in D["appr"]:
            rid = row["approval_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                when = stamp(row["decided_at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            pid = self.who(row["approver"])
            if pid is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            B.put(src, "accepted")
            if row["ticket"] in self.tk:
                self.tk[row["ticket"]]["votes"].append((when, rid, pid, row["decision"], stamp(row["recorded_at"])))
        fixes = defaultdict(list)
        for src, row in D["corr"]:
            rid = f"{row.get('ticket')}#{row.get('revision')}"
            if not self.seen(src, rid, row.get("recorded_at"), "s"):
                continue
            if "effective_until" not in row:
                B.put(src, "rejected", rid, "missing_field")
                continue
            try:
                v = None if row["effective_until"] is None else stamp(row["effective_until"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            if row["ticket"] in self.tk:
                fixes[row["ticket"]].append((int(row["revision"]), int(row["recorded_at"]), src, v))
            else:
                B.put(src, "accepted")
        for t, lst in fixes.items():
            lst.sort()
            for x in lst[:-1]:
                B.put(x[2], "collapsed")
            B.put(lst[-1][2], "accepted")
            self.tk[t]["fix"] = (lst[-1][3],)
        for src, row in D["ssr"]:
            rid = row["rev_id"]
            if not self.seen(src, rid, row["recorded_at"], "ms"):
                continue
            try:
                at = stamp(row["effective_at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            pid = self.who(row["revoker"])
            if pid is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            t = self.tk.get(row["ticket"])
            if t is None:
                B.put(src, "accepted")
            elif pid != t["ben"] and pid != t["req"]:
                B.put(src, "rejected", rid, "revoker_not_party")
            else:
                B.put(src, "accepted")
                t["cut"] = min(t["cut"], at)
        frozen = defaultdict(list)
        for w in D["freeze"]:
            frozen[w["env"]].append((stamp(w["start"]), stamp(w["end"])))
        self.held = []
        for rid, t in self.tk.items():
            env = t["env"]
            need = cfg[env + ".approvals_required"]
            asked = t["fix"][0] if t["fix"] else t["til"]
            t["asked"] = asked
            ok, veto = [], False
            order = sorted(t["votes"], key=(lambda v: (v[4], v[1])) if self.conv["start"] == "recorded" else None)
            for when, aid, pid, decision, rk in order:
                if not pid.startswith("emp:") or pid in (t["ben"], t["req"]) or not self.employed(pid, when):
                    continue
                if decision == "reject":
                    veto = True
                elif decision == "approve" and pid not in {p for _, p in ok}:
                    ok.append((rk if self.conv["start"] == "recorded" else when, pid))
            state = "vetoed" if veto else ("pending" if len(ok) < need else "approved")
            t["state"] = state
            if state != "approved":
                B.put(t["src"], "accepted")
                if asked is None or asked > E:
                    self.held.append((env, rid, state))
                continue
            begin = t["frm"] if t["frm"] is not None else t["rec"]
            if need and self.conv['start'] != 'requested':
                begin = max(begin, ok[-1 if self.conv['start'] == 'latest' else need - 1][0])
            end = min(NEVER if asked is None else asked, begin + cfg[env + ".max_grant_hours"] * 3600, t["cut"])
            t["begin"], t["end"] = begin, end
            if cfg[env + ".freeze_applies"] and any(a <= begin < b for a, b in frozen[env]):
                B.put(t["src"], "rejected", rid, "freeze_window")
                t["state"] = "frozen"
            else:
                B.put(t["src"], "accepted")

    def secops_layer(self):
        D, B = self.D, self.book
        self.bans = defaultdict(list)
        for src, row in D["sec"]:
            rid = row["case"]
            if not self.seen(src, rid, row.get("recorded_at"), "iso"):
                continue
            try:
                at = stamp(row["effective_at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            sc = row["scope"]
            if sc.startswith("perm:") and sc[5:] not in D["perms"]:
                B.put(src, "rejected", rid, "unknown_target")
                continue
            pid = self.who_any(row["subject"])
            if pid is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            B.put(src, "accepted")
            self.bans[pid].append((sc, at))

    def rota_layer(self):
        D, B = self.D, self.book
        weekly = defaultdict(list)
        for src, row in D["asg"]:
            rid = row["assignment_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                wk = day(row["week_start"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            if row["rotation"] not in D["rot"]:
                B.put(src, "rejected", rid, "unknown_target")
                continue
            pid = self.who(row["holder"])
            if pid is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            weekly[(row["rotation"], wk)].append((int(row["revision"]), stamp(row["recorded_at"]), src, pid))
        self.rota = {}
        for k, lst in weekly.items():
            lst.sort()
            for x in lst[:-1]:
                B.put(x[2], "collapsed")
            B.put(lst[-1][2], "accepted")
            self.rota[k] = lst[-1][3]
        swaps = defaultdict(list)
        for src, row in D["swp"]:
            rid = row["swap_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                dd = day(row["shift_date"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            if row["rotation"] not in D["rot"]:
                B.put(src, "rejected", rid, "unknown_target")
                continue
            a, b = self.who(row["from_holder"]), self.who(row["to_holder"])
            if a is None or b is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            swaps[(row["rotation"], dd)].append((stamp(row["recorded_at"]), rid, src, a, b))
        self.day_holder = {}
        for k, lst in swaps.items():
            cur = self.week_of(*k)
            for _, rid, src, a, b in sorted(lst):
                if cur is not None and a == cur:
                    cur = b
                    B.put(src, "accepted")
                else:
                    B.put(src, "rejected", rid, "swap_mismatch")
            self.day_holder[k] = cur

    def week_of(self, rot, dd):
        wd = datetime(*dd).weekday()
        return self.rota.get((rot, shift_day(dd, -wd)))

    def on_duty(self, rot, dd):
        return self.day_holder[(rot, dd)] if (rot, dd) in self.day_holder else self.week_of(rot, dd)

    def attest_layer(self):
        D, B = self.D, self.book
        self.reviews = defaultdict(list)
        for src, row in D["att"]:
            rid = row["attestation_id"]
            if not self.seen(src, rid, row["recorded_at"], "iso"):
                continue
            try:
                at = stamp(row["reviewed_at"])
            except Bad:
                B.put(src, "rejected", rid, "bad_timestamp")
                continue
            if row["permission"] not in D["perms"]:
                B.put(src, "rejected", rid, "unknown_target")
                continue
            a, b = self.who(row["reviewer"]), self.who(row["subject"])
            if a is None or b is None:
                B.put(src, "unresolved", rid, "unknown_handle")
                continue
            B.put(src, "accepted")
            if a != b:
                self.reviews[(b, row["permission"], row["env"])].append((at, rid, row["decision"]))

    # ------------------------------------------------------------------ per profile
    def shifts(self, env):
        E = self.E
        got = defaultdict(dict)
        for rid in sorted(self.D["rot"]):
            spec = self.D["rot"][rid]
            if spec["env"] != env:
                continue
            hh, mm = (int(x) for x in spec["start"].split(":"))
            dur = int(spec["duration_minutes"]) * 60
            step = 1 if spec["cadence"] == "daily" else 7

            def runs(dd):
                return spec["cadence"] == "daily" or datetime(*dd).weekday() == int(spec["weekday"])

            base = self.clock.date_of(spec["tz"], E)
            pick = None
            for k in range(9):
                dd = shift_day(base, -k)
                if not runs(dd):
                    continue
                s = self.clock.wall(spec["tz"], dd, hh, mm)
                if s <= E < s + dur and (pick is None or s > pick[1]):
                    pick = (dd, s)
            if pick is None:
                continue
            holder = self.on_duty(rid, pick[0])
            if holder is None:
                continue
            end = pick[1] + dur
            nd = shift_day(pick[0], step)
            for _ in range(800):
                s = self.clock.wall(spec["tz"], nd, hh, mm)
                if s > end or self.on_duty(rid, nd) != holder:
                    break
                end = max(end, s + dur)
                nd = shift_day(nd, step)
            for p in self.expand(spec["role"], env):
                got[holder][p] = max(got[holder].get(p, 0), end)
        return got

    def profile(self, env):
        D, E, cfg = self.D, self.E, self.cfg
        status = {}
        for pid in sorted(self.people):
            ok, _ = self.standing_of(pid, E)
            if not ok:
                status[pid] = "inactive"
            elif pid not in self.enabled:
                status[pid] = "disabled"
            elif cfg[env + ".require_mfa"] and not self.mfa_now(pid):
                status[pid] = "mfa_blocked"
            else:
                status[pid] = "eligible"
        bg = self.shifts(env)
        grants = defaultdict(lambda: defaultdict(list))
        live_tickets = 0
        for rid in sorted(self.tk):
            t = self.tk[rid]
            if t["env"] == env and t["state"] == "approved" and status.get(t["ben"]) == "eligible" and t["begin"] <= E and (E < t["end"] or (self.conv["window"] == "closed" and E == t["end"])):
                live_tickets += 1
                for p in t["perms"]:
                    grants[t["ben"]][p].append((t["begin"], t["end"]))
        gate = cfg[env + ".attestation_required"]
        sod = cfg[env + ".sod_enforced"]
        rules = sorted([x for x in D["sod"] if x["env"] == env], key=lambda x: x["rule"])
        days = cfg["attestation_max_age_days"]
        keys, unatt, sodlog = {}, [], []
        for pid, st in status.items():
            if st != "eligible":
                continue
            _, cap = self.standing_of(pid, E)
            base = {}
            for g, gcap in self.widest(pid).items():
                for role, hi in self.binds[env].get(g, ()):
                    for p in self.expand(role, env):
                        base[p] = max(base.get(p, 0), min(gcap, hi))
            extra = {p: v for p, v in grants.get(pid, {}).items()}
            duty = bg.get(pid, {})
            allp = set(base) | set(extra) | set(duty)
            if gate:
                for p in sorted(allp):
                    if D["perms"][p].get("critical") and (p in base or p in extra):
                        hist = sorted(x for x in self.reviews.get((pid, p, env), ()) if x[0] <= E)
                        fine = bool(hist) and hist[-1][2] == "keep" and hist[-1][0] >= E - days * 86400
                        if not fine:
                            base.pop(p, None)
                            extra.pop(p, None)
                            unatt.append((env, pid, p))
            if sod:
                for rule in rules:
                    a, b = rule["a"], rule["b"]
                    if not ((a in base or a in extra) and (b in base or b in extra)):
                        continue
                    if a in base and b in base:
                        sodlog.append((env, pid, rule["rule"], "standing_conflict", None))
                        continue
                    if a in base:
                        lose = b
                    elif b in base:
                        lose = a
                    else:
                        ta, tb = min(x[0] for x in extra[a]), min(x[0] for x in extra[b])
                        lose = a if ta > tb else (b if tb > ta else max(a, b))
                    del extra[lose]
                    sodlog.append((env, pid, rule["rule"], "suspended", lose))
            for p in allp:
                parts = []
                if p in base:
                    parts.append(base[p])
                if p in extra:
                    parts.append(max(x[1] for x in extra[p]))
                if p in duty:
                    parts.append(duty[p])
                if not parts:
                    continue
                ban = min([at for sc, at in self.bans.get(pid, ()) if sc in ("all", "env:" + env, "perm:" + p)], default=NEVER)
                v = min(max(parts), cap, ban)
                if v > E or (self.conv['window'] == 'closed' and v == E):
                    keys[pid + "|" + p] = (v, p in duty)
        return dict(keys=keys, status=status, unattested=unatt, sod=sodlog, live=live_tickets)

    def mfa_now(self, pid):
        hist = sorted(x for x in self.mfa.get(pid, ()) if x[0] <= self.E)
        return bool(hist) and hist[-1][2] == "enroll"


def everything(root, conv=None):
    """Return (config, profiles, audit, summary) documents for a corpus directory."""
    D = load(root)
    cfg, jrej, jtally = settle_config(D)
    W = World(D, cfg, conv)
    prof = {env: W.profile(env) for env in ("dev", "prod")}
    profiles = {env: {k: utc(v) for k, (v, _) in sorted(prof[env]["keys"].items())} for env in prof}
    checks = {}
    for src, t in W.book.tally.items():
        checks[src] = dict(t, records=sum(t.values()))
    checks["policy_change_journal.jsonl"] = jtally
    audit = {
        "rejects": [dict(source=a, record=b, reason=c) for a, b, c in sorted(set(W.book.rej + jrej))],
        "unresolved": [dict(source=a, record=b, reason=c) for a, b, c in sorted(set(W.book.unr))],
        "held_grants": [dict(profile=a, ticket=b, reason=c) for a, b, c in sorted(W.held)],
        "unattested": [dict(profile=e, principal=p, permission=q) for e in ("dev", "prod") for (_, p, q) in sorted(prof[e]["unattested"])],
        "sod": [dict(profile=e, principal=p, rule=r, outcome=o, permission=q) for e in ("dev", "prod")
                for (_, p, r, o, q) in sorted(prof[e]["sod"], key=lambda x: (x[1], x[2]))],
        "self_check": dict(sorted(checks.items())),
    }
    summary = {
        "as_of": cfg["as_of"], "recorded_cutoff": cfg["recorded_cutoff"],
        "profiles": {e: {"keys": len(prof[e]["keys"]), "principals": len({k.split("|")[0] for k in prof[e]["keys"]}),
                         "open_keys": sum(v >= NEVER for v, _ in prof[e]["keys"].values()),
                         "breakglass_keys": sum(1 for _, d in prof[e]["keys"].values() if d)} for e in prof},
        "eligibility": {e: {s: sum(1 for x in prof[e]["status"].values() if x == s)
                            for s in ("eligible", "inactive", "disabled", "mfa_blocked")} for e in prof},
        "grants": {e: {"active": prof[e]["live"],
                       "pending": sum(1 for a, _, c in W.held if a == e and c == "pending"),
                       "vetoed": sum(1 for a, _, c in W.held if a == e and c == "vetoed")} for e in prof},
        "audit_counts": {k: len(audit[k]) for k in ("rejects", "unresolved", "held_grants", "unattested", "sod")},
    }
    return cfg, profiles, audit, summary, W


# ===================================================================== held-out generator

DAY = 86400
HOUR = 3600


def ts(y, mo, d, h=0, mi=0, s=0) -> int:
    return calendar.timegm((y, mo, d, h, mi, s, 0, 0, 0))


def iso_z(t: int) -> str:
    return datetime.fromtimestamp(t, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def iso_off(t: int, off_min: int) -> str:
    if off_min == 0:
        return iso_z(t)
    local = datetime.fromtimestamp(t + off_min * 60, timezone.utc)
    sign = "+" if off_min > 0 else "-"
    a = abs(off_min)
    return local.strftime("%Y-%m-%dT%H:%M:%S") + f"{sign}{a // 60:02d}:{a % 60:02d}"


def ymd(t: int) -> str:
    return datetime.fromtimestamp(t, timezone.utc).strftime("%Y-%m-%d")


def date_add(day: str, n: int) -> str:
    d = datetime.strptime(day, "%Y-%m-%d") + timedelta(days=n)
    return d.strftime("%Y-%m-%d")


def nth_weekday(year, month, wd, n):
    """n-th weekday (0=Mon) of month; n=-1 is last."""
    if n > 0:
        d = datetime(year, month, 1)
        while d.weekday() != wd:
            d += timedelta(days=1)
        d += timedelta(days=7 * (n - 1))
    else:
        d = datetime(year, month, calendar.monthrange(year, month)[1])
        while d.weekday() != wd:
            d -= timedelta(days=1)
    return d.year, d.month, d.day


def zone_rules(kind: str, std: int, dst: int, years) -> dict:
    trans = []
    for y in years:
        if kind == "eu":
            a = nth_weekday(y, 3, 6, -1)
            b = nth_weekday(y, 10, 6, -1)
            trans += [(ts(*a, 1), "dst"), (ts(*b, 1), "std")]
        elif kind == "us":
            a = nth_weekday(y, 3, 6, 2)
            b = nth_weekday(y, 11, 6, 1)
            trans += [(ts(*a, 2) - std * 60, "dst"), (ts(*b, 2) - dst * 60, "std")]
        elif kind == "au":
            a = nth_weekday(y, 4, 6, 1)
            b = nth_weekday(y, 10, 6, 1)
            trans += [(ts(*a, 3) - dst * 60, "std"), (ts(*b, 2) - std * 60, "dst")]
        elif kind.startswith("custom"):
            _, m1, d1, m2, d2 = kind.split(":")
            trans += [(ts(y, int(m1), int(d1), 1), "dst"), (ts(y, int(m2), int(d2), 1), "std")]
    spec = {"std_offset_min": std}
    if kind != "none":
        spec["dst_offset_min"] = dst
        spec["transitions"] = [[iso_z(t), k] for t, k in sorted(trans)]
    return spec


