class Gen:
    def __init__(self, seed: int, scale: float, variant: str) -> None:
        self.r = random.Random(seed)
        self.scale = scale
        self.variant = variant
        self.files: dict[str, list] = {}
        self.texts: dict[str, str] = {}

    # ----------------------------------------------------------- utilities
    def n(self, base: int, floor: int) -> int:
        return max(floor, int(base * self.scale))

    def pick(self, seq):
        return seq[self.r.randrange(len(seq))]

    def chance(self, p: float) -> bool:
        return self.r.random() < p

    def any_iso(self, t: int) -> str:
        return iso_off(t, self.pick(self.offsets))

    def bad_iso(self, t: int) -> str:
        z = iso_z(t)
        kind = self.r.randrange(6)
        if kind == 0:
            return z.replace("T", " ")
        if kind == 1:
            return z[:-1]
        if kind == 2:
            return iso_off(t, 330).replace("+05:30", "+0530")
        if kind == 3:
            return z[:-1] + ".250Z"
        if kind == 4:
            return z[:-1] + "z"
        return z[:5] + "02-30" + z[10:]

    def bad_date(self, day: str) -> str:
        kind = self.r.randrange(3)
        if kind == 0:
            return day.replace("-", "/")
        if kind == 1:
            return day[:8] + "31" if day[5:7] in ("04", "06", "09", "11") else day[:5] + "02-30"
        return day + "T00:00:00Z"

    def trapped(self, name: str, normal: list, traps: list, keep_sorted=None) -> None:
        """First fifty rows are always ordinary rows; traps are spread after them."""
        self.r.shuffle(normal)
        head, tail = normal[:50], normal[50:] + traps
        self.r.shuffle(tail)
        rows = head + tail
        if keep_sorted is not None:
            rows = head + sorted(tail, key=keep_sorted)
        self.files[name] = rows

    # ----------------------------------------------------------- world
    def build(self) -> None:
        r = self.r
        heldout = self.variant != "shipped"
        if not heldout:
            self.E = ts(2026, 10, 28, 19, 30)
            self.R = ts(2026, 10, 28, 16, 0)
            years = (2025, 2026, 2027)
            self.zones = {
                "Europe/Berlin": zone_rules("eu", 60, 120, years),
                "Europe/London": zone_rules("eu", 0, 60, years),
                "America/New_York": zone_rules("us", -300, -240, years),
                "America/Los_Angeles": zone_rules("us", -480, -420, years),
                "Asia/Kolkata": zone_rules("none", 330, 330, years),
                "Australia/Sydney": zone_rules("au", 600, 660, years),
            }
            self.sites = {"ber": "Europe/Berlin", "lon": "Europe/London", "nyc": "America/New_York",
                          "sfo": "America/Los_Angeles", "blr": "Asia/Kolkata", "syd": "Australia/Sydney"}
            self.anchor_offset = 60
        else:
            base = ts(2027, 3, 1, 0, 0) + r.randrange(0, 40) * DAY
            self.E = base + r.randrange(6, 22) * HOUR + r.choice((0, 15, 30, 45)) * 60
            self.R = self.E - r.randrange(1, 9) * HOUR - r.choice((0, 30)) * 60
            years = (2026, 2027, 2028)
            m1 = 3
            d1 = r.randrange(5, 29)
            self.zones = {
                "Site/Arden": zone_rules(f"custom:{m1}:{d1}:10:{r.randrange(3, 28)}", 120, 180, years),
                "Site/Brisk": zone_rules("us", -360, -300, years),
                "Site/Cobalt": zone_rules("none", 345, 345, years),
                "Site/Dune": zone_rules("au", 570, 630, years),
                "Site/Ember": zone_rules("eu", 0, 60, years),
            }
            self.sites = {"ard": "Site/Arden", "brk": "Site/Brisk", "cob": "Site/Cobalt",
                          "dun": "Site/Dune", "emb": "Site/Ember"}
            self.anchor_offset = r.choice((-300, 0, 330, 540))
            if self.variant == "boundary":
                self.E = self.local_midnight("Site/Dune", ymd(self.E))
                self.R = self.E - 1
        self.offsets = sorted({0, 60, 120, -240, -300, -420, 330, 600, 660, 540, -180})
        self.start = self.E - 540 * DAY
        self.site_codes = sorted(self.sites)
        self.people()
        self.config_layers()
        self.catalog()
        self.directory()
        self.tickets()
        self.oncall()
        self.secops()
        self.attestations()
        self.manifest()

    # ----------------------------------------------------------- people
    def tz_offset(self, zone: str, t: int) -> int:
        spec = self.zones[zone]
        off = spec["std_offset_min"]
        trans = spec.get("transitions", [])
        cur = None
        for at, kind in trans:
            if ts(*map(int, (at[0:4], at[5:7], at[8:10], at[11:13], at[14:16], at[17:19]))) <= t:
                cur = kind
        if cur is None and trans:
            cur = "std" if trans[0][1] == "dst" else "dst"
        if cur == "dst":
            off = spec["dst_offset_min"]
        return off

    def local_midnight(self, zone: str, day: str) -> int:
        y, m, d = map(int, day.split("-"))
        local = ts(y, m, d)
        for o in sorted({self.zones[zone]["std_offset_min"], self.zones[zone].get("dst_offset_min", self.zones[zone]["std_offset_min"])}):
            if self.tz_offset(zone, local - o * 60) == o:
                return local - o * 60
        return local - self.zones[zone]["std_offset_min"] * 60

    def local_day(self, zone: str, t: int) -> str:
        return ymd(t + self.tz_offset(zone, t) * 60)

    def people(self) -> None:
        r = self.r
        heldout = self.variant != "shipped"
        n_emp = self.n(2000, 70)
        n_ctr = self.n(600, 24)
        lo, hi = (900000, 999999) if heldout else (40, 99999)
        nos = r.sample(range(lo, hi), n_emp)
        used = set()
        self.emps = []
        for no in nos:
            while True:
                h = f"{self.pick(FIRST)}.{self.pick(LAST)}"
                if h in used:
                    h = f"{h}{r.randrange(2, 99)}"
                if h not in used:
                    break
            used.add(h)
            self.emps.append({"no": no, "handle": h, "site": self.pick(self.site_codes)})
        lo, hi = (8000, 9999) if heldout else (10, 7999)
        cids = r.sample(range(lo, hi), n_ctr)
        self.ctrs = []
        for cid in cids:
            while True:
                h = f"x.{self.pick(FIRST)}.{self.pick(LAST)}"
                if h in used:
                    h = f"{h}{r.randrange(2, 99)}"
                if h not in used:
                    break
            used.add(h)
            self.ctrs.append({"id": cid, "handle": h, "site": self.pick(self.site_codes)})
        self.used_handles = used
        self.hr()
        self.contracts()
        self.accounts()

    def emp_ref(self, no: int, style=None) -> str:
        style = self.r.randrange(5) if style is None else style
        return [f"E{no:06d}", f"{no}", f"e-{no}", f"{no:06d}", f"E{no}"][style]

    def ctr_ref(self, cid: int, style=None) -> str:
        style = self.r.randrange(4) if style is None else style
        return [f"CTR-{cid:04d}", f"c{cid}", f"C-{cid:04d}", f"ctr{cid}"][style]

    def hr(self) -> None:
        r, E, R = self.r, self.E, self.R
        events = []
        corrections = []
        self.terminated = set()
        self.boundary_terms = []
        seq = 0

        def ev(emp, kind, day, rec, bucket=None):
            nonlocal seq
            seq += 1
            row = {"event_id": f"HRE-{seq:06d}", "employee_no": f"{emp['no']:06d}" if r.random() < 0.8 else str(emp["no"]),
                   "event": kind, "effective_date": day, "recorded_at": iso_z(rec)}
            events.append((row, bucket))
            return row

        early = self.E - 500 * DAY
        for emp in self.emps:
            hire_t = early - r.randrange(30, 3000) * DAY if r.random() < 0.85 else early + r.randrange(10, 470) * DAY
            hd = ymd(hire_t)
            ev(emp, "hire", hd, hire_t - r.randrange(5, 40) * DAY, "normal")
            emp["hire"] = hire_t
            roll = r.random()
            if roll < 0.12:
                t = hire_t + r.randrange(60, 900) * DAY
                if t < E - 2 * DAY:
                    ev(emp, "terminate", ymd(t), t - r.randrange(1, 30) * DAY, "normal")
                    self.terminated.add(emp["no"])
                    if r.random() < 0.3:
                        t2 = t + r.randrange(40, 200) * DAY
                        if t2 < E - 3 * DAY:
                            ev(emp, "rehire", ymd(t2), t2 - r.randrange(1, 20) * DAY, "normal")
                            self.terminated.discard(emp["no"])
            elif roll < 0.18:
                t = E - r.randrange(5, 200) * DAY
                ev(emp, "leave_start", ymd(t), t - r.randrange(1, 10) * DAY, "normal")
                if r.random() < 0.6:
                    t2 = t + r.randrange(10, 120) * DAY
                    ev(emp, "leave_end", ymd(t2), min(t2, R - DAY) - r.randrange(1, 5) * DAY, "normal")
            elif roll < 0.24:
                t = E + r.randrange(2, 60) * DAY
                ev(emp, "terminate", ymd(t), E - r.randrange(2, 30) * DAY, "trap")
        # boundary terminations and hires on the local date that straddles as_of
        tails = [e for e in self.emps if e["no"] not in self.terminated]
        r.shuffle(tails)
        for emp in tails[: self.n(120, 26)]:
            zone = self.sites[emp["site"]]
            today = self.local_day(zone, E)
            kind = r.choice(("today", "tomorrow", "tomorrow", "utcday"))
            if kind == "today":
                day = today
            elif kind == "tomorrow":
                day = date_add(today, 1)
            else:
                day = ymd(E + DAY)
            ev(emp, "terminate", day, E - r.randrange(3, 40) * DAY, "trap")
            self.boundary_terms.append((emp, day))
        for emp in tails[self.n(120, 26): self.n(150, 34)]:
            zone = self.sites[emp["site"]]
            day = date_add(self.local_day(zone, E), r.choice((0, 1)))
            emp["late_hire"] = True
            # replace history: a rehire that lands on the boundary day
            ev(emp, "terminate", ymd(E - r.randrange(40, 90) * DAY), E - 100 * DAY, "trap")
            ev(emp, "rehire", day, E - r.randrange(2, 20) * DAY, "trap")
        # events recorded after the cutoff
        for emp in r.sample(self.emps, self.n(60, 10)):
            t = E - r.randrange(1, 20) * DAY
            ev(emp, "terminate", ymd(t), R + r.randrange(60, 30 * HOUR), "trap")
        # malformed and unresolved events
        for emp in r.sample(self.emps, self.n(30, 8)):
            row = ev(emp, "leave_start", ymd(E - r.randrange(1, 90) * DAY), E - 100 * DAY, "trap")
            row["effective_date"] = self.bad_date(row["effective_date"])
        for _ in range(self.n(25, 6)):
            seq += 1
            events.append(({"event_id": f"HRE-{seq:06d}", "employee_no": str(r.randrange(100000, 899999)),
                            "event": "hire", "effective_date": ymd(E - 300 * DAY),
                            "recorded_at": iso_z(E - 310 * DAY)}, "trap"))
        # corrections: void or redate, sometimes several, one governing by recorded time
        evrows = [row for row, _ in events]
        cseq = 0
        for row, bucket in r.sample(events, self.n(260, 40)):
            n_corr = 1 if r.random() < 0.7 else r.randrange(2, 4)
            base = ts(*map(int, row["recorded_at"][:10].split("-")))
            for k in range(n_corr):
                cseq += 1
                action = "void" if r.random() < 0.35 else "redate"
                rec = min(base + r.randrange(1, 200) * DAY, R + r.randrange(-90, 4) * DAY)
                day = row["effective_date"] if not row["effective_date"][:4].isdigit() else row["effective_date"]
                try:
                    newday = date_add(day, r.choice((-3, -1, 1, 2, 7, 30)))
                except ValueError:
                    newday = ymd(E)
                corrections.append(({"correction_id": f"HRC-{cseq:05d}", "event_id": row["event_id"],
                                     "action": action, "new_effective_date": newday if action == "redate" else "",
                                     "recorded_at": iso_z(rec)}, "trap"))
        old_events = [row for row, _ in events if row["effective_date"][:4].isdigit() and row["effective_date"][4] == "-"
                      and row["event"] in ("hire", "terminate")
                      and ts(*map(int, row["effective_date"].split("-"))) < E - 400 * DAY]
        target = self.n(2050, 0) if self.variant == "shipped" else 0
        while len(corrections) < target and old_events:
            row = self.pick(old_events)
            cseq += 1
            rec = ts(*map(int, row["effective_date"].split("-"))) + r.randrange(2, 60) * DAY
            corrections.append(({"correction_id": f"HRC-{cseq:05d}", "event_id": row["event_id"], "action": "redate",
                                 "new_effective_date": date_add(row["effective_date"], r.choice((-2, -1, 1, 2))),
                                 "recorded_at": iso_z(min(rec, E - 300 * DAY))}, "normal"))
        for _ in range(self.n(12, 3)):
            cseq += 1
            target = self.pick(evrows)
            corrections.append(({"correction_id": f"HRC-{cseq:05d}", "event_id": target["event_id"], "action": "redate",
                                 "new_effective_date": self.bad_date(ymd(E)), "recorded_at": iso_z(E - 20 * DAY)}, "trap"))
        # split events by recorded period
        buckets = {"hr_events_2025.csv": [], "hr_events_2026h1.csv": [], "hr_events_2026h2.csv": []}
        cut1, cut2 = self.E - 300 * DAY, self.E - 120 * DAY
        for row, kind in events:
            rec = row["recorded_at"]
            t = ts(*map(int, (rec[0:4], rec[5:7], rec[8:10])))
            name = "hr_events_2025.csv" if t < cut1 else "hr_events_2026h1.csv" if t < cut2 else "hr_events_2026h2.csv"
            buckets[name].append((row, kind))
        busy = {row["employee_no"].lstrip("0") for row, _ in events if row["event"] != "hire"}
        plain = [e for e in self.emps if str(e["no"]) not in busy and e["hire"] < cut1 - 30 * DAY]
        if self.variant == "shipped":
            # pad thin periods with ordinary leave cycles recorded in that period
            for name, (lo_t, hi_t) in (("hr_events_2026h1.csv", (cut1, cut2)), ("hr_events_2026h2.csv", (cut2, R - DAY))):
                while len(buckets[name]) < 2050:
                    emp = self.pick(plain)
                    t = lo_t + r.randrange(0, (hi_t - lo_t) // DAY - 20) * DAY
                    seq += 1
                    a = {"event_id": f"HRE-{seq:06d}", "employee_no": f"{emp['no']:06d}", "event": "leave_start",
                         "effective_date": ymd(t), "recorded_at": iso_z(t - DAY)}
                    seq += 1
                    b = {"event_id": f"HRE-{seq:06d}", "employee_no": f"{emp['no']:06d}", "event": "leave_end",
                         "effective_date": ymd(t + r.randrange(2, 12) * DAY), "recorded_at": iso_z(t + 13 * DAY)}
                    buckets[name] += [(a, "normal"), (b, "normal")]
        for name, rows in buckets.items():
            normal = [x for x, k in rows if k == "normal"]
            traps = [x for x, k in rows if k != "normal"]
            self.trapped(name, normal, traps, keep_sorted=lambda x: x["recorded_at"])
        normal = [x for x, k in corrections if k == "normal"]
        traps = [x for x, k in corrections if k != "normal"]
        self.trapped("hr_corrections.csv", normal, traps)
        self.files["hr_employees.csv"] = [
            {"employee_no": f"{e['no']:06d}", "display_name": e["handle"].replace(".", " ").title(),
             "site": e["site"], "manager_no": f"{self.pick(self.emps)['no']:06d}",
             "cost_center": f"CC-{self.r.randrange(100, 999)}"} for e in sorted(self.emps, key=lambda e: e["no"])
        ]

    def contracts(self) -> None:
        r, E, R = self.r, self.E, self.R
        rows = []
        live_emps = [e for e in self.emps if e["no"] not in self.terminated]
        for c in self.ctrs:
            sponsor = self.pick(live_emps) if r.random() < 0.93 else self.pick(self.emps)
            c["sponsor"] = sponsor
            zone = self.sites[c["site"]]
            start = ymd(E - r.randrange(30, 600) * DAY)
            kind = r.random()
            if kind < 0.55:
                end = ymd(E + r.randrange(20, 300) * DAY)
            elif kind < 0.7:
                end = ymd(E - r.randrange(2, 200) * DAY)
            elif kind < 0.85:
                today = self.local_day(zone, E)
                end = r.choice((today, today, date_add(today, -1), date_add(today, 1)))
            else:
                end = ymd(E + r.randrange(1, 4) * DAY)
            n_am = r.randrange(2, 6)
            amendments = []
            s_t = ts(*map(int, start.split("-")))
            e_t = ts(*map(int, end.split("-")))
            for k in range(1, n_am + 1):
                cur_end = end if k == n_am else ymd(s_t + r.randrange(1, max(2, (e_t - s_t) // DAY + 30)) * DAY)
                rec = E - r.randrange(5, 500) * DAY
                amendments.append([k, cur_end, rec])
            if n_am >= 2 and r.random() < 0.35:
                # amendments recorded out of number order
                amendments[-1][2], amendments[-2][2] = min(amendments[-1][2], amendments[-2][2]), max(amendments[-1][2], amendments[-2][2])
            for k, cur_end, rec in amendments:
                rows.append(({"contractor_id": self.ctr_ref(c["id"], 0), "amendment_no": str(k), "site": c["site"],
                              "sponsor": self.emp_ref(sponsor["no"]), "start_date": start, "end_date": cur_end,
                              "recorded_at": iso_z(rec)}, "normal" if k < n_am else "trap"))
            if r.random() < 0.12:
                rows.append(({"contractor_id": self.ctr_ref(c["id"], 0), "amendment_no": str(n_am + 1), "site": c["site"],
                              "sponsor": self.emp_ref(sponsor["no"]), "start_date": start,
                              "end_date": ymd(E + 200 * DAY), "recorded_at": iso_z(R + r.randrange(60, 20 * HOUR))}, "trap"))
            c["end"] = end
        for c in r.sample(self.ctrs, self.n(14, 4)):
            rows.append(({"contractor_id": self.ctr_ref(c["id"], 0), "amendment_no": "9", "site": c["site"],
                          "sponsor": str(r.randrange(100000, 899999)), "start_date": ymd(E - 50 * DAY),
                          "end_date": ymd(E + 50 * DAY), "recorded_at": iso_z(E - 40 * DAY)}, "trap"))
        for c in r.sample(self.ctrs, self.n(10, 3)):
            rows.append(({"contractor_id": self.ctr_ref(c["id"], 0), "amendment_no": "8", "site": c["site"],
                          "sponsor": self.emp_ref(c["sponsor"]["no"]), "start_date": ymd(E - 50 * DAY),
                          "end_date": self.bad_date(ymd(E + 50 * DAY)), "recorded_at": iso_z(E - 45 * DAY)}, "trap"))
        for c in r.sample(self.ctrs, self.n(8, 3)):
            rows.append(({"contractor_id": self.ctr_ref(c["id"], 0), "amendment_no": "7", "site": c["site"],
                          "sponsor": self.emp_ref(c["sponsor"]["no"]), "start_date": ymd(E - 10 * DAY),
                          "end_date": ymd(E - 30 * DAY), "recorded_at": iso_z(E - 46 * DAY)}, "trap"))
        normal = [x for x, k in rows if k == "normal"]
        traps = [x for x, k in rows if k != "normal"]
        self.trapped("contractor_contracts.csv", normal, traps)

    def accounts(self) -> None:
        r, E, R = self.r, self.E, self.R
        east_sites = set(self.site_codes[: len(self.site_codes) // 2])
        rows = {"east": [], "west": []}
        self.handle_principal = {}
        self.renamed = []
        everyone = [("e", e) for e in self.emps] + [("c", c) for c in self.ctrs]
        for kind, p in everyone:
            shard = "east" if p["site"] in east_sites else "west"
            ref = self.emp_ref(p["no"]) if kind == "e" else self.ctr_ref(p["id"])
            gens = r.randrange(1, 5)
            t = E - r.randrange(200, 500) * DAY
            terminated = kind == "e" and p["no"] in self.terminated
            for g in range(1, gens + 1):
                t += r.randrange(10, 60) * DAY
                state = "enabled"
                if g == gens and terminated and r.random() < 0.7:
                    state = "disabled"
                rows[shard].append(({"handle": p["handle"] if r.random() < 0.8 else p["handle"].title(),
                                     "subject_ref": ref, "generation": g, "state": state,
                                     "synced_at": iso_z(min(t, R - HOUR))}, "normal"))
            p["gen"] = gens
            p["shard"] = shard
            self.handle_principal[p["handle"]] = (kind, p)
            if r.random() < 0.04 and not terminated:
                rows[shard].append(({"handle": p["handle"], "subject_ref": ref, "generation": gens + 1,
                                     "state": "disabled", "synced_at": iso_z(R + r.randrange(60, 40 * HOUR))}, "trap"))
            if r.random() < 0.025:
                rows[shard].append(({"handle": p["handle"], "subject_ref": ref, "generation": gens + 1,
                                     "state": "disabled", "synced_at": iso_z(E - r.randrange(2, 60) * DAY)}, "trap"))
                p["disabled"] = True
        # migrations: same handle in both shards with equal generation and a different state
        for kind, p in r.sample(everyone, self.n(70, 12)):
            other = "west" if p["shard"] == "east" else "east"
            ref = self.emp_ref(p["no"]) if kind == "e" else self.ctr_ref(p["id"])
            state = r.choice(("enabled", "disabled"))
            rows[other].append(({"handle": p["handle"].upper() if r.random() < 0.3 else p["handle"], "subject_ref": ref,
                                 "generation": p["gen"], "state": state,
                                 "synced_at": iso_z(R - r.randrange(2, 90) * DAY)}, "trap"))
            p["tie_state"] = (other, state)
        # renamed accounts: old handle kept as a second enabled account
        for kind, p in r.sample(everyone, self.n(110, 14)):
            old = f"{p['handle'].split('.')[0]}.{self.pick(LAST)}{r.randrange(2, 9)}"
            if old in self.used_handles:
                continue
            self.used_handles.add(old)
            ref = self.emp_ref(p["no"]) if kind == "e" else self.ctr_ref(p["id"])
            rows[p["shard"]].append(({"handle": old, "subject_ref": ref, "generation": 1, "state": "disabled",
                                      "synced_at": iso_z(E - r.randrange(100, 400) * DAY)}, "normal"))
            self.handle_principal[old] = (kind, p)
            self.renamed.append((old, p))
        # orphans
        self.orphans = []
        for i in range(self.n(40, 8)):
            h = f"{self.pick(FIRST)}.{self.pick(LAST)}.old{i}"
            self.used_handles.add(h)
            rows[r.choice(("east", "west"))].append(({"handle": h, "subject_ref": f"E{r.randrange(100000, 899999)}",
                                                     "generation": 1, "state": "enabled",
                                                     "synced_at": iso_z(E - r.randrange(30, 300) * DAY)}, "trap"))
            self.orphans.append(h)
        for i in range(self.n(14, 4)):
            p = self.pick(self.emps)
            rows["east"].append(({"handle": f"{p['handle']}.svc{i}", "subject_ref": self.emp_ref(p["no"]),
                                  "generation": 1, "state": "enabled", "synced_at": self.bad_iso(E - 30 * DAY)}, "trap"))
        for shard in ("east", "west"):
            normal = [x for x, k in rows[shard] if k == "normal"]
            traps = [x for x, k in rows[shard] if k != "normal"]
            self.trapped(f"idp_accounts_{shard}.jsonl", normal, traps)
        self.mfa_and_aliases()

    def handle_variant(self, h: str) -> str:
        k = self.r.randrange(4)
        return [h, h.title(), h.upper(), h][k]

    def ref_handle(self, p) -> str:
        """A handle form that refers to principal p: own handle, a case variant, or an alias."""
        aliases = self.alias_of.get(p["handle"], [])
        if aliases and self.r.random() < 0.2:
            return self.handle_variant(self.pick(aliases))
        return self.handle_variant(p["handle"])

    def mfa_and_aliases(self) -> None:
        r, E, R = self.r, self.E, self.R
        alias_rows = []
        self.alias_of = {}
        everyone = self.emps + self.ctrs
        for p in everyone:
            if r.random() < 0.8:
                a = f"{p['handle'].replace('.', '_')}@corp.mail"
                self.alias_of.setdefault(p["handle"], []).append(a)
                alias_rows.append(({"alias": a, "handle": p["handle"],
                                    "created_at": iso_z(E - r.randrange(30, 500) * DAY)}, "normal"))
        for old, p in self.renamed:
            pass
        late = r.sample(everyone, self.n(40, 8))
        for p in late:
            a = f"{p['handle'].split('.')[1]}.{p['handle'].split('.')[0][:1]}{r.randrange(10, 99)}"
            if a in self.used_handles:
                continue
            self.used_handles.add(a)
            alias_rows.append(({"alias": a, "handle": p["handle"], "created_at": iso_z(R + r.randrange(60, 30 * HOUR))}, "trap"))
            self.late_alias = getattr(self, "late_alias", []) + [(a, p)]
        for h in r.sample(self.orphans, min(len(self.orphans), self.n(20, 4))):
            alias_rows.append(({"alias": f"{h.replace('.', '_')}@corp.mail", "handle": h,
                                "created_at": iso_z(E - r.randrange(30, 300) * DAY)}, "trap"))
        stale = []
        taken = {row["alias"] for row, _ in alias_rows}
        for _ in range(self.n(25, 5)):
            a, b = r.sample(self.emps, 2)
            if a["handle"] in taken:
                continue
            taken.add(a["handle"])
            alias_rows.append(({"alias": a["handle"], "handle": b["handle"],
                                "created_at": iso_z(E - r.randrange(30, 300) * DAY)}, "trap"))
            stale.append(a["handle"])
        for p in r.sample(everyone, self.n(10, 3)):
            alias_rows.append(({"alias": f"{p['handle']}.legacy", "handle": p["handle"],
                                "created_at": self.bad_iso(E - 90 * DAY)}, "trap"))
        normal = [x for x, k in alias_rows if k == "normal"]
        traps = [x for x, k in alias_rows if k != "normal"]
        self.trapped("directory_aliases.tsv", normal, traps)

        lines = []
        seq = 0
        for p in everyone:
            t = E - r.randrange(100, 500) * DAY
            plan = ["enroll"]
            if r.random() < 0.18:
                plan.append("reset")
                if r.random() < 0.5:
                    plan.append("enroll")
            for k, action in enumerate(plan):
                t += r.randrange(5, 120) * DAY
                if t > R - HOUR:
                    t = R - r.randrange(2, 200) * HOUR
                seq += 1
                lines.append((t, f"mfa-{seq:06d}", action, self.ref_handle(p), t + r.randrange(1, 600), k > 0))
        for p in r.sample(everyone, self.n(45, 8)):
            t = E - r.randrange(1, 40) * HOUR
            seq += 1
            lines.append((t, f"mfa-{seq:06d}", "reset", self.ref_handle(p), R + r.randrange(10, 3 * HOUR), True))
            seq += 1
            lines.append((t - 3 * DAY, f"mfa-{seq:06d}", "reset", self.ref_handle(p), t - 3 * DAY + 50, True))
        for _ in range(self.n(20, 4)):
            seq += 1
            lines.append((E - 50 * DAY, f"mfa-{seq:06d}", "enroll", f"ghost.{self.pick(LAST)}{seq}", E - 50 * DAY + 9, True))
        out = []
        for t, eid, action, h, rec, trap in sorted(lines, key=lambda x: (x[0], x[1])):
            out.append(f"{iso_z(t)} {eid} {action} handle={h} recorded={iso_z(min(rec, rec))}")
        bad = []
        for _ in range(self.n(14, 4)):
            seq += 1
            p = self.pick(everyone)
            bad.append(f"{self.bad_iso(E - 10 * DAY)} mfa-{seq:06d} enroll handle={p['handle']} recorded={iso_z(E - 10 * DAY)}")
        for b in bad:
            out.insert(self.r.randrange(60, len(out)), b)
        self.texts["idp_mfa_events.log"] = "# warrant idp mfa event export\n" + "\n".join(out) + "\n"

    # ----------------------------------------------------------- config
    def config_layers(self) -> None:
        r, E, R = self.r, self.E, self.R
        shipped = self.variant == "shipped"
        self.schema = {
            "anchor_keys": ["as_of", "recorded_cutoff"],
            "profiles": ["dev", "prod"],
            "keys": {
                "attestation_max_age_days": {"scope": "global", "type": "int", "min": 1, "max": 365, "class": "ceiling"},
                "audit_log_retention_days": {"scope": "global", "type": "int", "min": 30, "max": 3650, "class": "ordinary"},
                "idp_shard_priority": {"scope": "global", "type": "enum", "values": ["east,west", "west,east"], "class": "ordinary"},
                "approvals_required": {"scope": "profile", "type": "int", "min": 0, "max": 3, "class": "ordinary"},
                "max_grant_hours": {"scope": "profile", "type": "int", "min": 1, "max": 720, "class": "ceiling"},
                "session_idle_minutes": {"scope": "profile", "type": "int", "min": 5, "max": 480, "class": "ceiling"},
                "require_mfa": {"scope": "profile", "type": "bool", "class": "ordinary"},
                "attestation_required": {"scope": "profile", "type": "bool", "class": "ordinary"},
                "freeze_applies": {"scope": "profile", "type": "bool", "class": "ordinary"},
                "sod_enforced": {"scope": "profile", "type": "bool", "class": "ordinary"},
            },
        }
        self.defaults = {"values": {
            "attestation_max_age_days": 180, "audit_log_retention_days": 365, "idp_shard_priority": "east,west",
            "approvals_required": 1, "max_grant_hours": 168, "session_idle_minutes": 60, "require_mfa": False,
            "attestation_required": False, "freeze_applies": False, "sod_enforced": True}}
        if shipped:
            prof = {"dev": {"max_grant_hours": 240, "session_idle_minutes": 120},
                    "prod": {"approvals_required": 2, "max_grant_hours": 72, "require_mfa": True,
                             "attestation_required": True, "freeze_applies": True, "session_idle_minutes": 30}}
            site = {"global": {"idp_shard_priority": "west,east", "attestation_max_age_days": "120"},
                    "dev": {"session_idle_minutes": "90"},
                    "prod": {"max_grant_hours": "96", "session_idle_minutes": "45"}}
        else:
            prof = {"dev": {"approvals_required": r.choice((0, 1)), "max_grant_hours": r.choice((48, 300))},
                    "prod": {"approvals_required": r.choice((2, 3)), "max_grant_hours": r.choice((24, 36, 60)),
                             "require_mfa": True, "attestation_required": True, "freeze_applies": True}}
            site = {"global": {"idp_shard_priority": r.choice(("west,east", "east,west")),
                               "attestation_max_age_days": str(r.choice((45, 60, 75)))},
                    "dev": {"session_idle_minutes": str(r.choice((20, 200)))},
                    "prod": {"max_grant_hours": str(r.choice((12, 400)))}}
        self.profiles_layer = prof
        self.site_layer = site
        rows = []
        seq = 0
        keys = ["audit_log_retention_days", "dev.session_idle_minutes", "prod.session_idle_minutes",
                "dev.require_mfa", "dev.freeze_applies", "attestation_max_age_days",
                "prod.max_grant_hours", "dev.max_grant_hours", "dev.approvals_required", "dev.sod_enforced"]

        def val(key):
            base = key.split(".")[-1]
            spec = self.schema["keys"][base]
            if spec["type"] == "bool":
                return r.random() < 0.5
            if base == "approvals_required":
                return r.choice((0, 1, 2))
            if base == "max_grant_hours":
                return r.choice((24, 48, 96, 120, 200, 336))
            if base == "attestation_max_age_days":
                return r.choice((60, 90, 150, 200))
            return r.randrange(spec["min"], spec["max"] + 1)

        def add(key, value, eff, rec, kind="normal", drop_value=False):
            nonlocal seq
            seq += 1
            row = {"seq": seq, "key": key, "value": value, "effective_at": eff, "recorded_at": rec}
            if drop_value:
                row.pop("value")
            rows.append((row, kind))

        noise_keys = ["audit_log_retention_days", "dev.require_mfa", "dev.freeze_applies", "dev.sod_enforced",
                      "dev.approvals_required", "prod.sod_enforced", "idp_shard_priority"]
        n_rows = self.n(2000, 50)
        for _ in range(n_rows):
            key = self.pick(noise_keys)
            eff_t = E - r.randrange(20, 360) * DAY - r.randrange(0, DAY)
            value = val(key) if key != "idp_shard_priority" else r.choice(("east,west", "west,east"))
            add(key, value, self.any_iso(eff_t), iso_z(eff_t - r.randrange(0, 5) * DAY))

        def seq_of(key, items):
            for eff_d, value, rec_d in items:
                eff = E - int(eff_d * DAY) if eff_d is not None else None
                rec = E - int(rec_d * DAY) if rec_d is not None else R + r.randrange(60, 2 * HOUR)
                add(key, value, self.any_iso(eff), iso_z(rec), "trap")

        hi_raise = r.choice((120, 144, 200))
        lo_ = r.choice((40, 48, 60))
        seq_of("prod.max_grant_hours", [(200, hi_raise, 201), (150, lo_, 151), (30, None, 31), (20, hi_raise + 24, 21),
                                        (0.25, 12, None), (-0.2, 10, 3)])
        seq_of("dev.max_grant_hours", [(100, r.choice((96, 120)), 101), (10, 200, 11)])
        seq_of("attestation_max_age_days", [(60, r.choice((80, 90, 100)), 61), (5, 150, 6)])
        seq_of("dev.session_idle_minutes", [(40, 45, 41), (20, None, 21), (10, 75, 11)])
        seq_of("prod.session_idle_minutes", [(15, r.choice((20, 25)), 16)])
        tail = {"dev.approvals_required": 1, "dev.require_mfa": False, "dev.freeze_applies": True, "dev.sod_enforced": True,
                "prod.sod_enforced": True, "idp_shard_priority": self.site_layer["global"]["idp_shard_priority"]}
        for key, value in tail.items():
            seq_of(key, [(r.randrange(8, 14), value, r.randrange(15, 30))])
        seq_of("dev.approvals_required", [(1, 0, None), (-1, 2, 2)])
        seq_of("prod.require_mfa", [(0.5, False, None)])
        flip = "east,west" if tail["idp_shard_priority"] == "west,east" else "west,east"
        seq_of("idp_shard_priority", [(3, flip, None)])
        r1, r2 = r.choice((400, 500)), r.choice((900, 1200))
        seq_of("audit_log_retention_days", [(4, r1, 5)])
        seq_of("audit_log_retention_days", [(8, r2, 1)])
        if r.random() < 0.5:
            seq_of("dev.sod_enforced", [(6, None, 7)])
        for _ in range(self.n(12, 3)):
            add(self.pick(["as_of", "recorded_cutoff"]), iso_z(E + DAY), self.any_iso(E - 3 * DAY), iso_z(E - 4 * DAY), "trap")
        for _ in range(self.n(12, 3)):
            add(self.pick(["prod.max_session_hours", "dev.break_glass_minutes", "audit_retention"]), 5,
                self.any_iso(E - 3 * DAY), iso_z(E - 4 * DAY), "trap")
        for _ in range(self.n(10, 3)):
            add(self.pick(noise_keys), None, self.any_iso(E - 6 * DAY), iso_z(E - 7 * DAY), "trap", drop_value=True)
        for _ in range(self.n(14, 3)):
            k = self.pick(["dev.approvals_required", "prod.max_grant_hours", "dev.require_mfa", "attestation_max_age_days"])
            bad = {"dev.approvals_required": 5, "prod.max_grant_hours": 0, "dev.require_mfa": "yes",
                   "attestation_max_age_days": 900}[k]
            add(k, bad, self.any_iso(E - 2 * DAY), iso_z(E - 2 * DAY - 600), "trap")
        for _ in range(self.n(10, 3)):
            add(self.pick(noise_keys), 40, self.bad_iso(E - 5 * DAY), iso_z(E - 6 * DAY), "trap")
        normal = [x for x, k in rows if k == "normal"]
        traps = [x for x, k in rows if k != "normal"]
        self.trapped("policy_change_journal.jsonl", normal, traps)

    # ----------------------------------------------------------- catalog
    def catalog(self) -> None:
        r = self.r
        domains = ["orders", "payments", "ledger", "iam", "billing", "search", "fleet", "warehouse", "support", "reports",
                   "pricing", "risk", "audit", "mail", "kyc"]
        if self.variant != "shipped":
            domains = domains[: 8]
        verbs = [("read", "both", False), ("write", "both", False), ("admin", "prod", True), ("deploy", "prod", True),
                 ("debug", "dev", False), ("export", "both", True), ("approve", "prod", True), ("initiate", "both", False)]
        perms = {}
        for d in domains:
            for res in ("api", "db", "batch"):
                for verb, scope, crit in verbs:
                    if r.random() < 0.55 or verb in ("read", "write"):
                        perms[f"{d}.{res}.{verb}"] = {"scope": scope, "critical": crit}
        self.perms = perms
        names = sorted(perms)
        roles = {"base-user": {"legacy_names": ["baseline"], "includes": [], "permissions": [p for p in names if p.endswith("api.read")][:2]}}
        self.role_names = ["base-user"]
        for d in domains:
            dperms = [p for p in names if p.startswith(d + ".")]
            reader = f"{d}-reader"
            roles[reader] = {"legacy_names": [f"{d}_ro"], "includes": ["base-user"],
                             "permissions": [p for p in dperms if p.endswith(".read")]}
            op = f"{d}-operator"
            roles[op] = {"legacy_names": [f"{d}_rw", f"{d.upper()}-OPS"], "includes": [reader],
                         "permissions": [p for p in dperms if p.endswith((".write", ".initiate", ".debug"))]}
            adm = f"{d}-admin"
            roles[adm] = {"legacy_names": [], "includes": [op],
                          "permissions": [p for p in dperms if p.endswith((".admin", ".deploy", ".export", ".approve"))]}
            bg = f"bg-{d}"
            roles[bg] = {"legacy_names": [f"breakglass_{d}"], "includes": [reader],
                         "permissions": [p for p in dperms if p.endswith((".admin", ".write", ".deploy"))]}
            self.role_names += [reader, op, adm]
        self.bg_roles = [f"bg-{d}" for d in domains]
        self.roles = roles
        self.domains = domains
        pairs = []
        k = 0
        for env in ("dev", "prod"):
            for d in domains:
                a, b = f"{d}.batch.approve", f"{d}.batch.initiate"
                if a in perms and b in perms and perms[a]["scope"] in (env, "both"):
                    k += 1
                    pairs.append({"rule": f"SOD-{k:02d}", "env": env, "a": a, "b": b})
                a, b = f"{d}.db.write", f"{d}.api.export"
                if a in perms and b in perms:
                    k += 1
                    pairs.append({"rule": f"SOD-{k:02d}", "env": env, "a": b, "b": a})
        self.sod = pairs

    # ----------------------------------------------------------- directory
    def directory(self) -> None:
        r, E, R = self.r, self.E, self.R
        n_groups = self.n(240, 18)
        site_keys = ["a", "b", "c", "d"]
        self.groups = [{"id": f"g-{i:04d}", "name": f"{self.pick(self.domains)}-{self.pick(['eng', 'ops', 'fin', 'sec', 'data', 'sup'])}-{i}",
                        "site": site_keys[i % 4]} for i in range(1, n_groups + 1)]
        gids = [g["id"] for g in self.groups]
        files = {k: [] for k in site_keys}
        seq = {k: 0 for k in site_keys}
        self.members = []

        def add(group, member, added, rec, kind="normal"):
            g = int(group[2:])
            key = site_keys[g % 4] if group in gids else self.pick(site_keys)
            seq[key] += 1
            mid = f"{key.upper()}-{seq[key]:06d}"
            row = {"mid": mid, "group_id": group, "member": member, "added_at": added, "recorded_at": rec}
            files[key].append((row, kind))
            self.members.append(row)
            return row

        everyone = self.emps + self.ctrs
        self.history_mids = []
        self.diamond_mids = []
        self.groups_of = {}
        for p in everyone:
            for _ in range(r.randrange(2, 5)):
                t = E - r.randrange(5, 480) * DAY
                g = self.pick(gids)
                self.groups_of.setdefault(p["handle"], []).append(g)
                add(g, self.ref_handle(p), self.any_iso(t), iso_z(t + r.randrange(0, 3 * DAY)))
            if r.random() < 0.25:
                t = E - r.randrange(400, 520) * DAY
                row = add(self.pick(gids), self.ref_handle(p), self.any_iso(t), iso_z(t + r.randrange(0, 3 * DAY)))
                self.history_mids.append((row["mid"], t))
        nest = []
        for i, g in enumerate(gids):
            for _ in range(1 if r.random() < 0.3 else 0):
                parent = self.pick(gids)
                if parent == g:
                    continue
                t = E - r.randrange(5, 400) * DAY
                nest.append(add(parent, f"group:{g}", self.any_iso(t), iso_z(t + 600)))
        trap_rows = []
        for _ in range(self.n(70, 10)):
            p = self.pick(everyone)
            kind = r.randrange(6)
            if kind == 0:
                trap_rows.append(add(self.pick(gids), self.ref_handle(p), self.any_iso(E), iso_z(E - 3 * DAY), "trap"))
            elif kind == 1:
                trap_rows.append(add(self.pick(gids), self.ref_handle(p), self.any_iso(E + r.randrange(1, 60) * 60), iso_z(E - 3 * DAY), "trap"))
            elif kind == 2:
                t = E - r.randrange(1, 20) * HOUR
                trap_rows.append(add(self.pick(gids), self.ref_handle(p), self.any_iso(t), iso_z(R + r.randrange(60, 3 * HOUR)), "trap"))
            elif kind == 3:
                trap_rows.append(add(self.pick(gids), self.ref_handle(p), self.bad_iso(E - 9 * DAY), iso_z(E - 9 * DAY), "trap"))
            elif kind == 4:
                trap_rows.append(add(f"g-{r.randrange(5000, 9999)}", self.ref_handle(p), self.any_iso(E - 9 * DAY), iso_z(E - 9 * DAY), "trap"))
            else:
                trap_rows.append(add(self.pick(gids), f"{self.pick(FIRST)}.{self.pick(LAST)}.gone{r.randrange(1, 99)}",
                                     self.any_iso(E - 9 * DAY), iso_z(E - 9 * DAY), "trap"))
        for _ in range(self.n(14, 4)):
            trap_rows.append(add(self.pick(gids), f"group:g-{r.randrange(5000, 9999)}", self.any_iso(E - 9 * DAY), iso_z(E - 9 * DAY), "trap"))
        # diamonds: a direct membership that ends soon beside an open nested route to the same group
        for _ in range(self.n(60, 8)):
            p = self.pick(everyone)
            x, y = r.sample(gids, 2)
            t = E - r.randrange(20, 200) * DAY
            row = add(x, self.ref_handle(p), self.any_iso(t), iso_z(t), "trap")
            self.diamond_mids.append(row["mid"])
            add(y, self.ref_handle(p), self.any_iso(t), iso_z(t), "trap")
            add(x, f"group:{y}", self.any_iso(t), iso_z(t), "trap")
        # cycles and deep chains
        for _ in range(self.n(10, 3)):
            a, b, c = r.sample(gids, 3)
            t = E - 100 * DAY
            add(b, f"group:{a}", self.any_iso(t), iso_z(t), "trap")
            add(c, f"group:{b}", self.any_iso(t), iso_z(t), "trap")
            add(a, f"group:{c}", self.any_iso(t), iso_z(t), "trap")
        for old, q in r.sample(self.renamed, min(len(self.renamed), self.n(40, 6))):
            add(self.pick(gids), old.upper() if r.random() < 0.3 else old, self.any_iso(E - 30 * DAY), iso_z(E - 30 * DAY), "trap")
        for la in getattr(self, "late_alias", []):
            add(self.pick(gids), la[0], self.any_iso(E - 30 * DAY), iso_z(E - 30 * DAY), "trap")
        for key in site_keys:
            normal = [x for x, k in files[key] if k == "normal"]
            traps = [x for x, k in files[key] if k != "normal"]
            self.trapped(f"dir_members_site_{key}.csv", normal, traps)
        # removals
        rem = []
        rseq = 0
        hist = dict(self.history_mids)
        for mid, t0 in self.history_mids:
            rseq += 1
            t = t0 + r.randrange(10, 300) * DAY
            rem.append(({"removal_id": f"RM-{rseq:06d}", "mid": mid, "removed_at": self.any_iso(t),
                         "recorded_at": iso_z(t + r.randrange(0, 2 * DAY))}, "normal"))
        for mid in self.diamond_mids:
            rseq += 1
            rem.append(({"removal_id": f"RM-{rseq:06d}", "mid": mid, "removed_at": self.any_iso(E + r.randrange(2, 90) * HOUR),
                         "recorded_at": iso_z(E - r.randrange(2, 20) * DAY)}, "trap"))
        skip = set(self.diamond_mids)
        for row in self.members:
            if row["mid"] in hist or row["mid"] in skip:
                continue
            if r.random() < 0.22:
                rseq += 1
                added = row["added_at"]
                kind = r.random()
                base = E - r.randrange(1, 300) * DAY
                if kind < 0.6:
                    t, rec, k = base, base + r.randrange(0, 2 * DAY), "normal"
                elif kind < 0.75:
                    t, rec, k = E + r.randrange(1, 400) * HOUR, E - r.randrange(1, 10) * DAY, "trap"
                elif kind < 0.82:
                    t, rec, k = E, E - 2 * DAY, "trap"
                elif kind < 0.9:
                    t, rec, k = E - r.randrange(1, 20) * HOUR, R + r.randrange(60, 3 * HOUR), "trap"
                else:
                    t, rec, k = E + r.randrange(2, 30) * DAY, E - 5 * DAY, "trap"
                rem.append(({"removal_id": f"RM-{rseq:06d}", "mid": row["mid"], "removed_at": self.any_iso(t),
                             "recorded_at": iso_z(rec)}, k))
                if r.random() < 0.08:
                    rseq += 1
                    rem.append(({"removal_id": f"RM-{rseq:06d}", "mid": row["mid"],
                                 "removed_at": self.any_iso(t + r.randrange(-5, 5) * DAY), "recorded_at": iso_z(rec + 3600)}, "trap"))
        for _ in range(self.n(12, 3)):
            rseq += 1
            rem.append(({"removal_id": f"RM-{rseq:06d}", "mid": self.pick(self.members)["mid"],
                         "removed_at": self.bad_iso(E - 4 * DAY), "recorded_at": iso_z(E - 4 * DAY)}, "trap"))
        normal = [x for x, k in rem if k == "normal"]
        traps = [x for x, k in rem if k != "normal"]
        self.trapped("dir_membership_removals.csv", normal, traps)
        # bindings
        self.prod_open = {}
        for env in ("dev", "prod"):
            rows = []
            bseq = 0
            readers = [x for x in self.role_names if x.endswith("-reader")]
            others = [x for x in self.role_names[1:] if not x.endswith("-reader")]
            for g in gids:
                shipped = self.variant == "shipped"
                bound_now = r.random() < ((0.2 if env == "prod" else 0.28) if shipped else 0.6)
                for _ in range(1 if bound_now else 0):
                    role = self.pick(readers) if r.random() < (0.7 if shipped else 0.3) else self.pick(others)
                    spec = self.roles[role]
                    name = role
                    if spec["legacy_names"] and r.random() < 0.2:
                        name = self.pick(spec["legacy_names"])
                    t0 = E - r.randrange(10, 500) * DAY
                    hist = r.random()
                    bseq += 1
                    if hist < 0.25:
                        t1 = t0 + r.randrange(5, 200) * DAY
                        rows.append(({"binding_id": f"B{env[0].upper()}-{bseq:05d}", "group_id": g, "role": name,
                                      "bound_from": self.any_iso(t0), "bound_until": self.any_iso(t1),
                                      "recorded_at": iso_z(t0)}, "normal"))
                        bseq += 1
                        t0 = t1
                    until = ""
                    kind = "normal"
                    if r.random() < 0.12:
                        until = self.any_iso(E + r.randrange(1, 900) * HOUR)
                        kind = "trap"
                    elif r.random() < 0.03:
                        until = self.any_iso(E)
                        kind = "trap"
                    rows.append(({"binding_id": f"B{env[0].upper()}-{bseq:05d}", "group_id": g, "role": name,
                                  "bound_from": self.any_iso(t0), "bound_until": until, "recorded_at": iso_z(t0)}, kind))
                    if env == "prod" and not until:
                        self.prod_open.setdefault(g, []).append(role)
            while self.variant == "shipped" and len(rows) < 2050:
                bseq += 1
                g = self.pick(gids)
                t0 = E - r.randrange(400, 520) * DAY
                rows.append(({"binding_id": f"B{env[0].upper()}-{bseq:05d}", "group_id": g, "role": self.pick(self.role_names[1:]),
                              "bound_from": self.any_iso(t0), "bound_until": self.any_iso(t0 + r.randrange(5, 60) * DAY),
                              "recorded_at": iso_z(t0)}, "normal"))
            for _ in range(self.n(16, 4)):
                bseq += 1
                t0 = E - r.randrange(3, 30) * DAY
                kind = r.randrange(4)
                row = {"binding_id": f"B{env[0].upper()}-{bseq:05d}", "group_id": self.pick(gids),
                       "role": self.pick(self.role_names[1:]), "bound_from": self.any_iso(t0), "bound_until": "",
                       "recorded_at": iso_z(t0)}
                if kind == 0:
                    row["role"] = "orders-superuser"
                elif kind == 1:
                    row["bound_until"] = self.any_iso(t0 - DAY)
                elif kind == 2:
                    row["bound_from"] = self.bad_iso(t0)
                else:
                    row["recorded_at"] = iso_z(R + r.randrange(60, 3 * HOUR))
                    row["bound_from"] = self.any_iso(E - 2 * HOUR)
                rows.append((row, "trap"))
            normal = [x for x, k in rows if k == "normal"]
            traps = [x for x, k in rows if k != "normal"]
            self.trapped(f"role_bindings_{env}.csv", normal, traps)

    # ----------------------------------------------------------- tickets
    def tickets(self) -> None:
        r, E, R = self.r, self.E, self.R
        months = ["2026_05", "2026_06", "2026_07", "2026_08", "2026_09", "2026_10"]
        live = [e for e in self.emps if e["no"] not in self.terminated]
        everyone = self.emps + self.ctrs
        shards = {m: [] for m in months}
        approvals = []
        corrections = []
        selfrev = []
        aseq = 0
        self.ticket_rows = []
        targets_role = [f"role:{x}" for x in self.role_names[1:]] + [f"role:{x}" for x in ("orders_rw", "PAYMENTS-OPS", "baseline")]
        targets_perm = [f"perm:{p}" for p in sorted(self.perms)]
        sod_targets = [p for pair in self.sod for p in (pair["a"], pair["b"])]
        month_span = len(months)
        per_month = self.n(2010, 30)

        def approve(tid, who_handle, decided, rec, decision="approve", kind="normal"):
            nonlocal aseq
            aseq += 1
            approvals.append(({"approval_id": f"AP-{aseq:06d}", "ticket": tid, "approver": who_handle,
                               "decision": decision, "decided_at": self.any_iso(decided), "recorded_at": iso_z(rec)}, kind))

        for mi, month in enumerate(months):
            month_start = E - (month_span - mi) * 30 * DAY
            for k in range(per_month):
                tid = f"T{month.replace('_', '')[2:]}-{k:05d}"
                env = "prod" if r.random() < 0.55 else "dev"
                ben = self.pick(everyone)
                req = ben if r.random() < 0.6 else self.pick(live)
                late = mi == month_span - 1 and r.random() < 0.3
                t_rec = month_start + r.randrange(0, 29 * DAY)
                if late:
                    t_rec = E - r.randrange(1, 96) * HOUR
                    t_rec = min(t_rec, R - 600)
                frm = t_rec + r.randrange(0, 48) * HOUR
                dur = r.choice((4, 8, 12, 24, 48, 72, 120, 200))
                until = frm + dur * HOUR
                target = self.pick(targets_perm if r.random() < 0.5 else targets_role)
                if env == "prod" and target.startswith("perm:") and self.perms[target[5:]]["scope"] == "dev":
                    target = "perm:" + self.pick([p for p in sorted(self.perms) if self.perms[p]["scope"] != "dev"])
                if env == "dev" and target.startswith("perm:") and self.perms[target[5:]]["scope"] == "prod":
                    target = "perm:" + self.pick([p for p in sorted(self.perms) if self.perms[p]["scope"] != "prod"])
                if late and r.random() < 0.35:
                    target = "perm:" + self.pick(sod_targets)
                row = {"ticket": tid, "export_generation": 1, "beneficiary": self.ref_handle(ben),
                       "requester": self.ref_handle(req), "env": env, "target": target,
                       "effective_from": self.any_iso(frm), "effective_until": self.any_iso(until),
                       "recorded_at": iso_z(t_rec)}
                kind = "trap" if late else "normal"
                if r.random() < 0.06:
                    row["effective_until"] = None
                    kind = "trap"
                if r.random() < 0.04:
                    row["effective_from"] = None
                    kind = "trap"
                shards[month].append((row, kind))
                self.ticket_rows.append((row, ben, req, frm, until))
                # approvals
                need = self.profiles_layer["prod"].get("approvals_required", 2) if env == "prod" else 1
                approvers = r.sample(live, 4)
                n_ok = need if r.random() < 0.85 else need - 1
                dec = t_rec + r.randrange(10, 600) * 60
                if late and r.random() < 0.5:
                    dec = frm + r.randrange(1, 40) * HOUR
                elif self.variant == "conv" and r.random() < 0.25:
                    dec = frm + r.randrange(1, 40) * HOUR
                for j in range(n_ok + (1 if r.random() < 0.2 else 0)):
                    a = approvers[j]
                    d = dec + j * r.randrange(60, 7200)
                    approve(tid, self.ref_handle(a), d, d + r.randrange(5, 4000), kind=kind)
                if r.random() < 0.08:
                    approve(tid, self.ref_handle(ben), dec - 300, dec - 200, kind="trap")
                if r.random() < 0.05 and req is not ben:
                    approve(tid, self.ref_handle(req), dec - 200, dec - 100, kind="trap")
                if r.random() < 0.03:
                    approve(tid, self.ref_handle(approvers[3]), dec + 50, dec + 90, "reject", kind="trap")
                if r.random() < 0.04:
                    approve(tid, self.ref_handle(self.pick(self.ctrs)), dec + 60, dec + 80, kind="trap")
                if r.random() < 0.05 and n_ok >= 1:
                    approve(tid, self.ref_handle(approvers[0]), dec + 90, dec + 120, kind="trap")
        # separation of duties: a standing side beside an elevated side, and two elevated sides
        last = months[-1]
        sod_seq = 0
        holders = [e for e in live if any(any(x.endswith("-operator") or x.endswith("-admin") for x in self.prod_open.get(g, []))
                                          for g in self.groups_of.get(e["handle"], []))]
        for emp in r.sample(holders, min(len(holders), self.n(30, 6))):
            roles = [x for g in self.groups_of[emp["handle"]] for x in self.prod_open.get(g, []) if x.endswith(("-operator", "-admin"))]
            d = self.pick(roles).split("-")[0]
            pairs = [(pp["a"], pp["b"]) for pp in self.sod if pp["env"] == "prod" and pp["a"].startswith(d + ".")]
            if not pairs:
                continue
            a, b = self.pick(pairs)
            standing_side = b if b.endswith(".write") or b.endswith(".initiate") else a
            other = a if standing_side == b else b
            frm_list = [E - r.randrange(4, 30) * HOUR]
            targets = [other]
            if r.random() < 0.5:
                mine = {x.split("-")[0] for g in self.groups_of[emp["handle"]] for x in self.prod_open.get(g, [])}
                free = [pp for pp in self.sod if pp["env"] == "prod" and pp["a"].split(".")[0] not in mine]
                if free:
                    pair = self.pick(free)
                    targets = [pair["a"], pair["b"]]
                    first = E - r.randrange(5, 30) * HOUR
                    frm_list = [first, first + r.choice((-1, 1)) * r.randrange(1, 4) * HOUR]
            for perm, frm in zip(targets, frm_list):
                sod_seq += 1
                tid = f"T{last.replace('_', '')[2:]}-9{sod_seq:04d}"
                row = {"ticket": tid, "export_generation": 1, "beneficiary": self.ref_handle(emp),
                       "requester": self.ref_handle(emp), "env": "prod", "target": f"perm:{perm}",
                       "effective_from": self.any_iso(frm), "effective_until": self.any_iso(frm + 40 * HOUR),
                       "recorded_at": iso_z(frm - 3 * HOUR)}
                shards[last].append((row, "trap"))
                self.ticket_rows.append((row, emp, emp, frm, frm + 40 * HOUR))
                for a2 in r.sample([x for x in live if x is not emp], 2):
                    dd = frm - r.randrange(30, 150) * 60
                    approve(tid, self.ref_handle(a2), dd, dd + 120, kind="trap")
        # requests starting exactly on a freeze boundary
        for k, (env, at) in enumerate([("prod", E - 3 * HOUR)] * self.n(6, 3) + [("prod", E - 7 * HOUR)] * self.n(3, 2)
                                      + [("dev", E - 2 * HOUR)] * self.n(4, 2)):
            emp = self.pick(live)
            tid = f"T{last.replace('_', '')[2:]}-8{k:04d}"
            row = {"ticket": tid, "export_generation": 1, "beneficiary": self.ref_handle(emp), "requester": self.ref_handle(emp),
                   "env": env, "target": self.pick(targets_role), "effective_from": self.any_iso(at),
                   "effective_until": self.any_iso(at + 30 * HOUR), "recorded_at": iso_z(at - 5 * HOUR)}
            shards[last].append((row, "trap"))
            self.ticket_rows.append((row, emp, emp, at, at + 30 * HOUR))
            for a2 in r.sample([x for x in live if x is not emp], 3 if env == "prod" else 1):
                dd = at - r.randrange(60, 200) * 60
                approve(tid, self.ref_handle(a2), dd, dd + 90, kind="trap")
        # late approvals for old tickets: request filed months ago, approved near as_of
        late_tids = set()
        mark = len(approvals)
        for month in months[:-1]:
            pool = [t for t in self.ticket_rows if t[0]["ticket"].startswith("T" + month.replace("_", "")[2:])]
            for _ in range(self.n(28, 3)):
                row, ben, req, frm, until = self.pick(pool)
                if row["ticket"] in late_tids:
                    continue
                late_tids.add(row["ticket"])
                row["effective_until"] = None if r.random() < 0.5 else self.any_iso(E + r.randrange(20, 400) * HOUR)
                live2 = [e for e in live if e is not ben and e is not req]
                for j, a in enumerate(r.sample(live2, r.choice((2, 3, 3)))):
                    d = E - r.randrange(2, 70) * HOUR if self.variant == "shipped" else E - r.randrange(2, 10) * HOUR - r.randrange(0, 3600)
                    approve(row["ticket"], self.ref_handle(a), d, min(d + 300, R - 60), kind="trap")
        approvals = [x for i, x in enumerate(approvals) if i >= mark or x[0]["ticket"] not in late_tids]
        # approvers whose employment ended on the boundary day
        for emp, day in self.boundary_terms[: self.n(40, 8)]:
            row, ben, req, frm, until = self.pick(self.ticket_rows[-per_month:])
            zone = self.sites[emp["site"]]
            mid = self.local_midnight(zone, day)
            d = mid + r.choice((-1800, 1800))
            if d < R - 120:
                approve(row["ticket"], self.ref_handle(emp), d, d + 60, kind="trap")
        # re-exports and duplicates
        for _ in range(self.n(90, 10)):
            mi = r.randrange(0, month_span - 1)
            src_month, dst_month = months[mi], months[r.randrange(mi + 1, month_span)]
            base_row = self.pick(shards[src_month])[0]
            copy = dict(base_row)
            roll = r.random()
            if roll < 0.4:
                pass
            elif roll < 0.75:
                copy["export_generation"] = 2
                copy["effective_until"] = self.any_iso(E + r.randrange(5, 50) * HOUR)
                copy["effective_from"] = self.any_iso(E - r.randrange(5, 50) * HOUR)
            else:
                copy["effective_until"] = self.any_iso(E + r.randrange(5, 50) * HOUR)
            shards[dst_month].append((copy, "trap"))
        # malformed requests
        for month in months:
            for _ in range(self.n(14, 3)):
                row = dict(self.pick(shards[month])[0])
                row["ticket"] = row["ticket"] + "X"
                kind = r.randrange(5)
                if kind == 0:
                    row.pop("effective_until")
                elif kind == 1:
                    row["effective_from"] = self.bad_iso(E - 2 * DAY)
                elif kind == 2:
                    row["effective_until"] = self.any_iso(E - 3 * DAY)
                    row["effective_from"] = self.any_iso(E - 2 * DAY)
                elif kind == 3:
                    row["target"] = self.pick(["role:root", "perm:orders.db.drop", "role:orders-superuser"])
                else:
                    if row["env"] == "prod":
                        devp = [p for p in sorted(self.perms) if self.perms[p]["scope"] == "dev"]
                        row["target"] = "perm:" + self.pick(devp)
                    else:
                        row["beneficiary"] = f"nobody.{self.pick(LAST)}"
                shards[month].append((row, "trap"))
        for month in months:
            normal = [x for x, k in shards[month] if k == "normal"]
            traps = [x for x, k in shards[month] if k != "normal"]
            self.trapped(f"grant_requests_{month}.jsonl", normal, traps)
        normal = [x for x, k in approvals if k == "normal"]
        traps = [x for x, k in approvals if k != "normal"]
        for _ in range(self.n(12, 3)):
            aseq += 1
            traps.append({"approval_id": f"AP-{aseq:06d}", "ticket": self.pick(self.ticket_rows)[0]["ticket"],
                          "approver": self.pick(live)["handle"], "decision": "approve",
                          "decided_at": self.bad_iso(E - 3 * DAY), "recorded_at": iso_z(E - 3 * DAY)})
        self.trapped("grant_approvals.csv", normal, traps)
        # corrections
        recent = [t for t in self.ticket_rows if t[3] > E - 30 * DAY]
        older = [t for t in self.ticket_rows if t[3] <= E - 30 * DAY]
        for row, ben, req, frm, until in r.sample(older, min(len(older), self.n(1700, 10))):
            rec = frm + r.randrange(1, 20) * HOUR
            corrections.append(({"ticket": row["ticket"], "revision": 1, "effective_until": self.any_iso(until + r.randrange(-5, 30) * HOUR),
                                 "recorded_at": rec}, "normal"))
        for row, ben, req, frm, until in r.sample(recent, min(len(recent), self.n(300, 14))):
            revs = r.randrange(1, 4)
            order = list(range(1, revs + 1))
            if revs > 1 and r.random() < 0.5:
                r.shuffle(order)
            base = max(frm, E - 4 * DAY)
            for i, rev in enumerate(order):
                rec = base + i * r.randrange(600, 20000)
                if r.random() < 0.12:
                    rec = R + r.randrange(1, 3 * HOUR)
                elif rec > R:
                    rec = R - r.randrange(60, 3000)
                val = None if r.random() < 0.15 else self.any_iso(E + r.randrange(-30, 200) * HOUR)
                corrections.append(({"ticket": row["ticket"], "revision": rev, "effective_until": val,
                                     "recorded_at": rec}, "trap"))
        for _ in range(self.n(12, 3)):
            row = self.pick(recent)[0]
            corrections.append(({"ticket": row["ticket"], "revision": 9, "recorded_at": E - 3 * DAY}, "trap"))
        for _ in range(self.n(12, 3)):
            row = self.pick(recent)[0]
            corrections.append(({"ticket": row["ticket"], "revision": 8, "effective_until": self.bad_iso(E + DAY),
                                 "recorded_at": E - 3 * DAY}, "trap"))
        normal = [x for x, k in corrections if k == "normal"]
        traps = [x for x, k in corrections if k != "normal"]
        self.trapped("grant_corrections.jsonl", normal, traps)
        # self service revocations
        rseq = 0
        for row, ben, req, frm, until in r.sample(self.ticket_rows, min(len(self.ticket_rows), self.n(2050, 20))):
            rseq += 1
            near = frm > E - 10 * DAY
            if near:
                at = E + r.randrange(-30, 60) * HOUR
                rec_ms = (min(at, R) - r.randrange(60, 7200)) * 1000 + r.randrange(0, 999)
                kind = "trap"
            else:
                at = frm + r.randrange(1, 10) * HOUR
                rec_ms = at * 1000 + r.randrange(0, 999)
                kind = "normal"
            who = ben if r.random() < 0.7 else req
            if r.random() < 0.08:
                who = self.pick(live)
                kind = "trap"
            selfrev.append(({"rev_id": f"SR-{rseq:06d}", "ticket": row["ticket"], "revoker": self.ref_handle(who),
                             "effective_at": self.any_iso(at), "recorded_at": str(rec_ms)}, kind))
        for _ in range(self.n(16, 4)):
            rseq += 1
            row, ben, req, frm, until = self.pick(recent)
            selfrev.append(({"rev_id": f"SR-{rseq:06d}", "ticket": row["ticket"], "revoker": self.ref_handle(ben),
                             "effective_at": self.any_iso(E - 2 * HOUR), "recorded_at": str(R * 1000 + r.randrange(1, 999))}, "trap"))
        for _ in range(self.n(10, 3)):
            rseq += 1
            row, ben, req, frm, until = self.pick(recent)
            selfrev.append(({"rev_id": f"SR-{rseq:06d}", "ticket": row["ticket"], "revoker": self.ref_handle(ben),
                             "effective_at": self.any_iso(E - 2 * HOUR), "recorded_at": str(R * 1000)}, "trap"))
        normal = [x for x, k in selfrev if k == "normal"]
        traps = [x for x, k in selfrev if k != "normal"]
        self.trapped("revocations_selfservice.csv", normal, traps)
        # freeze windows
        self.freeze = [
            {"env": "prod", "start": iso_off(E - 7 * HOUR, 60), "end": iso_z(E - 3 * HOUR), "reason": "quarter close"},
            {"env": "prod", "start": iso_z(E - 40 * DAY), "end": iso_z(E - 38 * DAY), "reason": "datacentre move"},
            {"env": "dev", "start": iso_z(E - 6 * HOUR), "end": iso_z(E - 2 * HOUR), "reason": "lab rebuild"},
        ]

    # ----------------------------------------------------------- oncall
    def oncall(self) -> None:
        r, E, R = self.r, self.E, self.R
        rots = []
        zones = list(self.zones)
        n_rot = self.n(20, 8)
        for i in range(n_rot):
            cad = "daily" if i % 3 != 2 else "weekly"
            tz = zones[i % len(zones)]
            dur = r.choice((720, 1440, 1440)) if cad == "daily" else r.choice((10080, 10080, 4320))
            start = r.choice(("18:00", "09:00", "07:30", "20:00")) if cad == "daily" else "09:00"
            rots.append({"id": f"rot-{i:02d}", "env": "prod" if i % 4 else "dev", "role": self.bg_roles[i % len(self.bg_roles)],
                         "tz": tz, "cadence": cad, "weekday": 0, "start": start, "duration_minutes": dur})
        self.rotations = rots
        live = [e for e in self.emps if e["no"] not in self.terminated]
        rows, swaps = [], []
        aseq = sseq = 0
        weeks = []
        monday = datetime.fromtimestamp(E - 90 * 7 * DAY, timezone.utc)
        while monday.weekday() != 0:
            monday -= timedelta(days=1)
        for w in range(104):
            weeks.append((monday + timedelta(days=7 * w)).strftime("%Y-%m-%d"))
        self.week_holder = {}
        for rot in rots:
            team = r.sample(live, 5)
            for w, week in enumerate(weeks):
                holder = team[w % 5] if r.random() < 0.85 else self.pick(team)
                aseq += 1
                wt = ts(*map(int, week.split("-")))
                rec = wt - r.randrange(3, 20) * DAY
                if rec > R:
                    rec = R - DAY
                kind = "normal" if wt < E - 30 * DAY else "trap"
                rows.append(({"assignment_id": f"OA-{aseq:05d}", "rotation": rot["id"], "week_start": week,
                              "holder": self.ref_handle(holder), "revision": 1, "recorded_at": iso_z(rec)}, kind))
                self.week_holder[(rot["id"], week)] = holder
                if wt > E - 21 * DAY and r.random() < 0.5:
                    other = self.pick(team)
                    aseq += 1
                    rec2 = min(rec + r.randrange(1, 9) * DAY, R + (r.randrange(60, 3600) if r.random() < 0.3 else -3600))
                    rows.append(({"assignment_id": f"OA-{aseq:05d}", "rotation": rot["id"], "week_start": week,
                                  "holder": self.ref_handle(other), "revision": 2 if r.random() < 0.8 else 3, "recorded_at": iso_z(rec2)}, "trap"))
            # swaps
            n_swaps = self.n(100, 8)
            cur = {}
            last_rec = {}
            for _ in range(n_swaps):
                w = r.randrange(0, len(weeks))
                if r.random() < 0.3:
                    w = 90 + r.randrange(-2, 2)
                week = weeks[w]
                day = date_add(week, r.randrange(0, 7)) if rot["cadence"] == "daily" else week
                holder = cur.get(day, self.week_holder[(rot["id"], week)])
                frm = holder if r.random() < 0.93 else self.pick(team)
                to = self.pick([t for t in team if t is not frm])
                sseq += 1
                wt = ts(*map(int, day.split("-")))
                rec = wt - r.randrange(1, 5) * DAY
                if rec > R:
                    rec = R - 3600
                rec = max(rec, last_rec.get(day, 0) + 600)
                last_rec[day] = rec + 600
                kind = "normal" if wt < E - 30 * DAY and frm is holder else "trap"
                swaps.append(({"swap_id": f"SW-{sseq:05d}", "rotation": rot["id"], "shift_date": day,
                               "from_holder": self.ref_handle(frm), "to_holder": self.ref_handle(to), "recorded_at": iso_z(rec)}, kind))
                if frm is holder and rec <= R:
                    cur[day] = to
                if r.random() < 0.15:
                    sseq += 1
                    swaps.append(({"swap_id": f"SW-{sseq:05d}", "rotation": rot["id"], "shift_date": day,
                                   "from_holder": self.ref_handle(to), "to_holder": self.ref_handle(frm), "recorded_at": iso_z(rec + 600)}, "trap"))
                    if cur.get(day) is to and rec + 600 <= R:
                        cur[day] = frm
        for _ in range(self.n(10, 3)):
            aseq += 1
            rows.append(({"assignment_id": f"OA-{aseq:05d}", "rotation": f"rot-{90 + r.randrange(9)}", "week_start": weeks[-2],
                          "holder": self.pick(live)["handle"], "revision": 1, "recorded_at": iso_z(E - 20 * DAY)}, "trap"))
        for _ in range(self.n(8, 3)):
            aseq += 1
            rows.append(({"assignment_id": f"OA-{aseq:05d}", "rotation": self.pick(rots)["id"], "week_start": self.bad_date(weeks[-3]),
                          "holder": self.pick(live)["handle"], "revision": 4, "recorded_at": iso_z(E - 20 * DAY)}, "trap"))
        for _ in range(self.n(10, 3)):
            sseq += 1
            swaps.append(({"swap_id": f"SW-{sseq:05d}", "rotation": self.pick(rots)["id"], "shift_date": weeks[-1],
                           "from_holder": f"temp.{self.pick(LAST)}", "to_holder": self.pick(live)["handle"],
                           "recorded_at": iso_z(E - 3 * DAY)}, "trap"))
        normal = [x for x, k in rows if k == "normal"]
        traps = [x for x, k in rows if k != "normal"]
        self.trapped("oncall_assignments.csv", normal, traps)
        normal = [x for x, k in swaps if k == "normal"]
        traps = [x for x, k in swaps if k != "normal"]
        self.trapped("oncall_swaps.csv", normal, traps)

    # ----------------------------------------------------------- secops
    def secops(self) -> None:
        r, E, R = self.r, self.E, self.R
        rows = []
        k = 0
        term = [e for e in self.emps if e["no"] in self.terminated]
        live = [e for e in self.emps if e["no"] not in self.terminated]
        perms = sorted(self.perms)
        for _ in range(self.n(1900, 20)):
            k += 1
            p = self.pick(term) if term and r.random() < 0.9 else self.pick(self.emps)
            subj = self.emp_ref(p["no"]) if r.random() < 0.6 else self.ref_handle(p)
            t = E - r.randrange(30, 500) * DAY
            scope = self.pick(["all", "all", "env:prod"]) if p in term else "perm:" + self.pick(perms)
            rows.append(({"case": f"SEC-{k:05d}", "subject": subj, "scope": scope, "effective_at": self.any_iso(t),
                          "recorded_at": iso_z(t + r.randrange(0, 5) * DAY)}, "normal"))
        for _ in range(self.n(130, 14)):
            k += 1
            p = self.pick(live + self.ctrs)
            subj = (self.emp_ref(p["no"]) if "no" in p else self.ctr_ref(p["id"])) if r.random() < 0.5 else self.ref_handle(p)
            roll = r.random()
            scope = "all" if roll < 0.2 else ("env:prod" if roll < 0.4 else ("env:dev" if roll < 0.5 else "perm:" + self.pick(perms)))
            when = r.random()
            if when < 0.4:
                eff, rec = E + r.randrange(1, 200) * HOUR, E - r.randrange(1, 10) * DAY
            elif when < 0.7:
                eff, rec = E - r.randrange(1, 30) * DAY, R - r.randrange(1, 40) * HOUR
            elif when < 0.85:
                eff, rec = E - r.randrange(1, 10) * HOUR, R + r.randrange(60, 3 * HOUR)
            else:
                eff, rec = E, E - 2 * DAY
            rows.append(({"case": f"SEC-{k:05d}", "subject": subj, "scope": scope, "effective_at": self.any_iso(eff),
                          "recorded_at": iso_z(rec)}, "trap"))
        for _ in range(self.n(10, 3)):
            k += 1
            rows.append(({"case": f"SEC-{k:05d}", "subject": f"E{r.randrange(100000, 899999)}", "scope": "all",
                          "effective_at": self.any_iso(E - 4 * DAY), "recorded_at": iso_z(E - 4 * DAY)}, "trap"))
        for _ in range(self.n(8, 3)):
            k += 1
            p = self.pick(live)
            rows.append(({"case": f"SEC-{k:05d}", "subject": p["handle"], "scope": "perm:orders.db.drop",
                          "effective_at": self.any_iso(E - 4 * DAY), "recorded_at": iso_z(E - 4 * DAY)}, "trap"))
        for _ in range(self.n(8, 3)):
            k += 1
            p = self.pick(live)
            rows.append(({"case": f"SEC-{k:05d}", "subject": p["handle"], "scope": "all",
                          "effective_at": self.bad_iso(E - 4 * DAY), "recorded_at": iso_z(E - 4 * DAY)}, "trap"))
        normal = [x for x, k2 in rows if k2 == "normal"]
        traps = [x for x, k2 in rows if k2 != "normal"]
        self.trapped("revocations_secops.jsonl", normal, traps)

    # ----------------------------------------------------------- attestations
    def attestations(self) -> None:
        r, E, R = self.r, self.E, self.R
        rows = []
        k = 0
        crit = [p for p in sorted(self.perms) if self.perms[p]["critical"]]
        everyone = self.emps + self.ctrs
        live = [e for e in self.emps if e["no"] not in self.terminated]
        campaigns = [E - d * DAY for d in (200, 150, 118, 95, 60, 30, 9)]
        self.pending_observations = []
        n_rows = self.n(2100, 60)
        for _ in range(n_rows):
            k += 1
            subj = self.pick(everyone)
            rev = self.pick(live)
            perm = self.pick(crit) if r.random() < 0.8 else self.pick(sorted(self.perms))
            when = self.pick(campaigns) + r.randrange(0, 5 * DAY)
            if when > R:
                when = R - HOUR
            row = {"attestation_id": f"AT-{k:06d}", "reviewer": self.ref_handle(rev), "subject": self.ref_handle(subj),
                   "permission": perm, "env": "prod" if r.random() < 0.85 else "dev", "reviewed_at": self.any_iso(when),
                   "decision": "keep" if r.random() < 0.9 else "revoke", "observed_state": "in_effect",
                   "recorded_at": iso_z(min(when + r.randrange(60, 3 * DAY), R - 60))}
            rows.append((row, "normal" if when < E - 100 * DAY else "trap"))
            self.pending_observations.append(row)
        for _ in range(self.n(20, 4)):
            k += 1
            subj = self.pick(live)
            rows.append(({"attestation_id": f"AT-{k:06d}", "reviewer": self.ref_handle(subj), "subject": self.ref_handle(subj),
                          "permission": self.pick(crit), "env": "prod", "reviewed_at": self.any_iso(E - 5 * DAY),
                          "decision": "keep", "observed_state": "in_effect", "recorded_at": iso_z(E - 5 * DAY)}, "trap"))
        for _ in range(self.n(10, 3)):
            k += 1
            rows.append(({"attestation_id": f"AT-{k:06d}", "reviewer": self.pick(live)["handle"], "subject": self.pick(live)["handle"],
                          "permission": "orders.db.drop", "env": "prod", "reviewed_at": self.any_iso(E - 5 * DAY),
                          "decision": "keep", "observed_state": "in_effect", "recorded_at": iso_z(E - 5 * DAY)}, "trap"))
        self.attest_rows = rows
        self.attest_seq = k

    # ----------------------------------------------------------- output
    def manifest(self) -> None:
        pass

    def write(self, out: Path) -> None:
        out.mkdir(parents=True, exist_ok=True)
        import csv
        import io

        def csv_text(rows, delim=","):
            buf = io.StringIO()
            w = csv.DictWriter(buf, fieldnames=list(rows[0].keys()), delimiter=delim, lineterminator="\n")
            w.writeheader()
            for row in rows:
                w.writerow(row)
            return buf.getvalue()

        for name, rows in self.files.items():
            if name.endswith(".jsonl"):
                text = "".join(json.dumps(row, separators=(", ", ": ")) + "\n" for row in rows)
            elif name.endswith(".tsv"):
                text = csv_text(rows, "\t")
            else:
                text = csv_text(rows)
            (out / name).write_text(text, encoding="utf-8")
        for name, text in self.texts.items():
            (out / name).write_text(text, encoding="utf-8")
        dumpj = lambda name, doc: (out / name).write_text(json.dumps(doc, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        dumpj("config_schema.json", self.schema)
        dumpj("defaults.json", self.defaults)
        dumpj("tz_rules.json", {"zones": self.zones})
        dumpj("hr_sites.json", {"sites": {code: {"tz": tz} for code, tz in sorted(self.sites.items())}})
        dumpj("role_catalog.json", {"roles": self.roles})
        dumpj("sod_policy.json", {"pairs": self.sod})
        dumpj("dir_groups.json", {"groups": self.groups})
        dumpj("oncall_rotations.json", {"rotations": self.rotations})
        dumpj("freeze_windows.json", {"windows": self.freeze})
        lines = []
        for perm in sorted(self.perms):
            spec = self.perms[perm]
            lines.append(f'[permissions."{perm}"]\nscope = "{spec["scope"]}"\ncritical = {"true" if spec["critical"] else "false"}\n')
        (out / "permission_catalog.toml").write_text("\n".join(lines), encoding="utf-8")
        prof = []
        for env in ("dev", "prod"):
            prof.append(f"[{env}]")
            for key, value in self.profiles_layer[env].items():
                prof.append(f"{key} = {json.dumps(value)}")
            prof.append("")
        (out / "profiles.toml").write_text("\n".join(prof), encoding="utf-8")
        ini = ["[anchor]", f"as_of = {iso_off(self.E, self.anchor_offset)}",
               f"recorded_cutoff = {iso_off(self.R, self.anchor_offset)}", ""]
        for section in ("global", "dev", "prod"):
            ini.append(f"[{section}]")
            for key, value in self.site_layer.get(section, {}).items():
                ini.append(f"{key} = {value}")
            ini.append("")
        (out / "site_policy.ini").write_text("\n".join(ini), encoding="utf-8")
        att = [row for row, _ in self.attest_rows]
        (out / "access_attestations.csv").write_text(csv_text(att), encoding="utf-8")
        names = sorted(p.name for p in out.iterdir() if p.is_file() and p.suffix != ".md" and p.name != "tool.zip")
        names.append("corpus_manifest.json")
        dumpj("corpus_manifest.json", {"files": sorted(set(names))})


def generate(out: Path, seed: int, scale: float, variant: str) -> Gen:
    g = Gen(seed, scale, variant)
    g.build()
    g.write(Path(out))
    return g


# ===================================================================== held-out tiers

def attest_from_reference(root: Path, g, seed: int) -> None:
    r = random.Random(seed * 7 + 3)
    D = load(root)
    cfg, _, _ = settle_config(D)
    cfg = dict(cfg)
    cfg["prod.attestation_required"] = False
    cfg["prod.sod_enforced"] = False
    W = World(D, cfg)
    days = int(cfg["attestation_max_age_days"])
    E, R = W.E, W.R
    prof = W.profile("prod")
    live = sorted(p for p, s in prof["status"].items() if s == "eligible" and p.startswith("emp:"))
    hand = {p: sorted(h) for p, h in W.mine.items()}
    rows, seq = [], 0

    def h(pid):
        hs = hand.get(pid)
        return r.choice(hs) if hs else None

    def add(rev, subj, perm, at, decision, rec):
        nonlocal seq
        seq += 1
        rows.append({"attestation_id": f"AT-{seq:06d}", "reviewer": rev, "subject": subj, "permission": perm,
                     "env": "prod", "reviewed_at": iso_off(at, r.choice(g.offsets)), "decision": decision,
                     "observed_state": "in_effect", "recorded_at": iso_z(rec)})

    lo = E - days * 86400
    for key, (value, duty) in sorted(prof["keys"].items()):
        pid, perm = key.split("|")
        if not D["perms"][perm].get("critical") or duty:
            continue
        subj, rev = h(pid), h(r.choice(live))
        if subj is None or rev is None:
            continue
        roll = r.random()
        if roll < 0.55:
            at = lo + r.randrange(3600, max(7200, R - lo - 3600))
            add(rev, subj, perm, at, "keep", min(at + 600, R - 1))
        elif roll < 0.65:
            add(rev, subj, perm, lo - r.randrange(60, 30 * 86400), "keep", lo)
        elif roll < 0.72:
            add(rev, subj, perm, lo, "keep", lo + 60)
        elif roll < 0.79:
            at = lo + 3 * 86400
            add(rev, subj, perm, at, "keep", at + 60)
            add(rev, subj, perm, at + 3600, "revoke", at + 3700)
        elif roll < 0.86:
            add(subj, subj, perm, lo + 86400, "keep", lo + 86460)
        elif roll < 0.93:
            at = lo + 2 * 86400
            add(rev, subj, perm, at, "keep", R + r.randrange(1, 3600))
    if not rows:
        add(h(live[0]), h(live[-1]), sorted(D["perms"])[0], E - 86400, "keep", E - 86000)
    buf = io.StringIO()
    w = csv.DictWriter(buf, fieldnames=list(rows[0]), lineterminator="\n")
    w.writeheader()
    for row in rows:
        w.writerow(row)
    (root / "access_attestations.csv").write_text(buf.getvalue(), encoding="utf-8")


def build(root: Path, seed: int, scale: float, variant: str = "heldout", conv=None) -> None:
    g = generate(root, seed, scale, variant)
    attest_from_reference(root, g, seed)
    observe(root, g, seed, conv)


def shuffle_records(src: Path, dst: Path, seed: int) -> None:
    r = random.Random(seed)
    dst.mkdir(parents=True, exist_ok=True)
    for p in sorted(src.iterdir()):
        text = p.read_text(encoding="utf-8")
        if p.suffix in (".csv", ".tsv"):
            lines = text.splitlines()
            body = lines[1:]
            r.shuffle(body)
            text = "\n".join([lines[0]] + body) + "\n"
        elif p.suffix in (".jsonl", ".log"):
            lines = [x for x in text.splitlines() if x.strip()]
            head = [x for x in lines if x.startswith("#")]
            body = [x for x in lines if not x.startswith("#")]
            r.shuffle(body)
            text = "\n".join(head + body) + "\n"
        (dst / p.name).write_text(text, encoding="utf-8")


# ===================================================================== gateway observations
GATE_ENVS = ("dev", "prod")


def gateway_cfg(D, at, memo=None):
    if memo is not None and at in memo:
        return memo[at]
    D2 = dict(D)
    D2["site"] = {k: dict(v) for k, v in D["site"].items()}
    D2["site"]["anchor"]["as_of"] = D2["site"]["anchor"]["recorded_cutoff"] = utc(at)
    c, _, _ = settle_config(D2)
    c = dict(c)
    for e in GATE_ENVS:
        c[e + ".attestation_required"] = False
        c[e + ".sod_enforced"] = False
    if memo is not None:
        memo[at] = c
    return c


def gateway_states(D, rows, conv, memo=None):
    """observed_state the gateway shows for each row under conventions conv."""
    by_at = defaultdict(list)
    for i, row in enumerate(rows):
        by_at[stamp(row["reviewed_at"])].append(i)
    out = [None] * len(rows)
    for at in sorted(by_at):
        W = World(D, gateway_cfg(D, at, memo), conv)
        keys = {}
        for i in by_at[at]:
            row = rows[i]
            env = row["env"]
            if env not in keys:
                keys[env] = W.profile(env)["keys"]
            pid = W.who(row["subject"])
            out[i] = "in_effect" if pid is not None and pid + "|" + row["permission"] in keys[env] else "not_in_effect"
    return out


def observe(root: Path, g, seed: int, conv=None) -> None:
    conv = dict(SHIPPED_CONV, **(conv or {}))
    r = random.Random(seed * 13 + 7)
    path = root / "access_attestations.csv"
    rows = list(csv.DictReader(io.StringIO(path.read_text(encoding="utf-8"))))
    fields = list(rows[0])
    D = load(root)
    cfg, _, _ = settle_config(D)
    cfg = dict(cfg)
    for e in GATE_ENVS:
        cfg[e + ".attestation_required"] = False
        cfg[e + ".sod_enforced"] = False
    W0 = World(D, cfg, conv)
    E, R = W0.E, W0.R
    live = sorted(p for p, s in W0.profile("prod")["status"].items() if s == "eligible" and p.startswith("emp:"))
    hand = {p: sorted(h) for p, h in W0.mine.items()}
    seq = max(int(x["attestation_id"].split("-")[1]) for x in rows)
    new = []
    memo = {}

    def add(pid, perm, env, at):
        nonlocal seq
        rev = r.choice([p for p in live if p != pid and hand.get(p)])
        seq += 1
        new.append({"attestation_id": f"AT-{seq:06d}", "reviewer": r.choice(hand[rev]), "subject": r.choice(hand[pid]),
                    "permission": perm, "env": env, "reviewed_at": iso_off(at, r.choice(g.offsets)), "decision": "keep",
                    "observed_state": "", "recorded_at": iso_z(min(at + 600, R - 1))})

    def held(at, pid):
        c = gateway_cfg(D, at, memo)
        W = World(D, c, conv)
        return sorted((e, k.split("|")[1]) for e in GATE_ENVS for k in W.profile(e)["keys"] if k.startswith(pid + "|"))

    lo_lim, hi_lim = E - 300 * DAY, min(E, R) - 2 * HOUR
    zones = sorted(D["tz"])
    alts = [("hr", h) for h in ["site", "utc"] + ["zone:" + z for z in zones] if h != conv["hr"]]
    alts += [("start", v) for v in ("requested", "decided", "recorded", "latest") if v != conv["start"]]
    alts += [("window", v) for v in ("half", "closed") if v != conv["window"]]
    kills = {a: 0 for a in alts}

    def row(pid, perm, env, at):
        return {"subject": hand[pid][0], "permission": perm, "env": env, "reviewed_at": iso_z(at)}, (pid, perm, env, at)

    def group(specs):
        rs = [row(*x) for x in specs]
        return [x[0] for x in rs], [x[1] for x in rs]

    def try_specs(dim, specs):
        rs, sp = group(specs)
        open_ = [a for a in alts if a[0] == dim and kills[a] < 2]
        if not open_ or not rs:
            return
        base = gateway_states(D, rs, conv, memo)
        keep = set()
        for a in open_:
            st = gateway_states(D, rs, dict(conv, **{a[0]: a[1]}), memo)
            hit = [i for i in range(len(rs)) if st[i] != base[i]]
            if hit:
                kills[a] += 1
                keep.update(hit)
        for i in sorted(keep):
            add(*sp[i])

    # HR clock evidence: instants between the candidate readings of an event's date
    evs = sorted((eid, pid, kind, dd) for eid, (pid, kind, dd) in W0.hr_ev.items())
    r.shuffle(evs)
    probes = 0
    for eid, pid, kind, dd in evs:
        if probes >= 40 or all(kills[a] >= 2 for a in alts if a[0] == "hr"):
            break
        if not hand.get(pid) or kind not in ("terminate", "hire", "rehire", "leave_start", "leave_end"):
            continue
        tz = W0.emp_tz[pid]
        bs = sorted({W0.clock.wall(tz, dd), _epoch(*dd)} | {W0.clock.wall(z, dd) for z in zones})
        lo_i, hi_i = bs[0] - 3 * HOUR, bs[-1] + 3 * HOUR
        if not (lo_lim < lo_i and hi_i < hi_lim):
            continue
        probes += 1
        on = held(lo_i if kind in ("terminate", "leave_start") else hi_i, pid)
        if not on:
            continue
        env, perm = r.choice(on)
        ats = [lo_i] + [(a + b) // 2 for a, b in zip(bs, bs[1:]) if b - a >= 120] + [hi_i]
        try_specs("hr", [(pid, perm, env, at) for at in ats])
    # grant start and window evidence: instants between candidate grant ends, and the planted end itself
    Ws = {s: World(D, cfg, dict(conv, start=s)) for s in ("requested", "decided", "recorded", "latest")}
    cands = []
    for rid in sorted(W0.tk):
        ts_ = [Ws[s].tk[rid] for s in Ws]
        if any(t.get("state") != "approved" for t in ts_) or W0.tk[rid]["ben"] not in hand:
            continue
        ends = sorted({t["end"] for t in ts_})
        if ends[0] - 2 * HOUR < lo_lim or ends[-1] + 2 * HOUR > hi_lim:
            continue
        cands.append(rid)
    r.shuffle(cands)
    cands.sort(key=lambda rid: -len({Ws[s].tk[rid]["end"] for s in Ws}))
    for rid in cands[:60]:
        if all(kills[a] >= 2 for a in alts if a[0] in ("start", "window")):
            break
        t = W0.tk[rid]
        ends = sorted({Ws[s].tk[rid]["end"] for s in Ws})
        perm = sorted(t["perms"])[0]
        ats = sorted({ends[0] - 1800, t["end"], t["end"] - 1, ends[-1] + 1800} | {(a + b) // 2 for a, b in zip(ends, ends[1:])})
        specs = [(t["ben"], perm, t["env"], at) for at in ats]
        if len(ends) > 1:
            try_specs("start", specs)
        try_specs("window", specs)
    observe.kills = dict(kills)
    rows += new
    states = gateway_states(D, rows, conv, memo)
    for row, st in zip(rows, states):
        row["observed_state"] = st
    buf = io.StringIO()
    w = csv.DictWriter(buf, fieldnames=fields, lineterminator="\n")
    w.writeheader()
    for row in rows:
        w.writerow(row)
    path.write_text(buf.getvalue(), encoding="utf-8")


