def profile_prod_keys_exact(workspace: Path) -> bool:
    try:
        got, exp = _artifact("profile_prod.json"), _expected_shipped()[1]["prod"]
        return isinstance(got, dict) and set(got) == set(exp)
    except Exception:
        return False


