@criterion(description="summary.json equals the recomputed summary and its counts match the delivered profiles and report")
def summary_identity_triangle(workspace: Path) -> bool:
    try:
        summ, exp = _artifact("summary.json"), _expected_shipped()[3]
        if summ != exp:
            return False
        report = _artifact("validation_report.json")
        for profile in ("dev", "prod"):
            prof = _artifact(f"profile_{profile}.json")
            if not isinstance(prof, dict) or summ["profiles"][profile]["keys"] != len(prof):
                return False
            if summ["profiles"][profile]["principals"] != len({k.split("|", 1)[0] for k in prof}):
                return False
        return all(summ["audit_counts"][k] == len(report[k]) for k in summ["audit_counts"])
    except Exception:
        return False


